import {UsagePeriod} from '../enums'
import {DEFAULT_PREMIUM_REQUESTS_GROUP_TYPE} from '../constants'
import type {Filters} from '../types/usage'

/**
 * Creates URLSearchParams from usage filters for URL synchronization
 */
export function createUsageUrlParams(filters: Filters): URLSearchParams {
  const period = filters.period?.type ?? UsagePeriod.DEFAULT
  const group = filters.group?.type ?? DEFAULT_PREMIUM_REQUESTS_GROUP_TYPE

  const params = new URLSearchParams()
  params.set('period', period.toString())
  params.set('group', group.toString())
  params.set('customer', filters.customer.id)

  if (filters.chartSelection?.value !== undefined) {
    params.set('chart_selection', filters.chartSelection.value.toString())
  }

  if (filters.searchQuery) {
    params.set('query', filters.searchQuery)
  }

  if (filters.page && filters.page > 1) {
    params.set('page', filters.page.toString())
  }

  return params
}
