import {useRoutePayload} from '@github-ui/react-core/use-route-payload'
import {Banner, Heading} from '@primer/react'
import {clsx} from 'clsx'
import {useState} from 'react'
import {DiscountForm} from '../../components/stafftools/discounts/DiscountForm'
import {DiscountUsageCard} from '../../components/usage'
import {useDiscounts} from '../../hooks/discount'
import styles from './DiscountsPage.module.css'

import type {Customer} from '../../types/common'
import type {EnabledProduct} from '../../types/products'

export interface DiscountsPagePayload {
  customer: Customer
  enabledProducts: EnabledProduct[]
  isEnterpriseOrgOwner: boolean
  isCopilotPremiumUsageReportEnabled: boolean
  is_token_based_billing_enabled?: boolean
}

export function DiscountsPage() {
  const {
    customer,
    enabledProducts,
    isEnterpriseOrgOwner,
    isCopilotPremiumUsageReportEnabled,
    is_token_based_billing_enabled: isTokenBasedBillingEnabled,
  } = useRoutePayload<DiscountsPagePayload>()
  const [showSuccessBanner, setShowSuccessBanner] = useState(false)
  const [showErrorBanner, setShowErrorBanner] = useState(false)

  const handleSuccess = () => {
    setShowErrorBanner(false)
    setShowSuccessBanner(true)
    window.scrollTo({top: 0, behavior: 'smooth'})
    refetch()
  }

  const handleError = () => {
    setShowErrorBanner(true)
    setShowSuccessBanner(false)
    window.scrollTo({top: 0, behavior: 'smooth'})
  }

  const {
    discountStates,
    enabledProductDiscountStates,
    enabledProductDiscountTargetAmounts,
    isLoadingDiscounts,
    refetch,
  } = useDiscounts({enabledProducts})
  const totalDiscount = enabledProductDiscountStates.reduce((acc, discount) => acc + discount.currentAmount, 0)

  return (
    <>
      <div>
        {showSuccessBanner && (
          <Banner
            aria-label="Success"
            title="Success"
            description="Credit successfully created."
            onDismiss={() => setShowSuccessBanner(false)}
            className="tmp-mb-3"
          />
        )}

        {showErrorBanner && (
          <Banner
            aria-label="Critical"
            title="Error"
            description="There was an issue creating your credit. Please try again."
            onDismiss={() => setShowErrorBanner(false)}
            variant="critical"
            className="tmp-mb-3"
          />
        )}
      </div>
      <header className="Subhead">
        <Heading as="h2" className={clsx('Subhead-heading', styles.pageHeading)}>
          Credits
        </Heading>
      </header>
      <DiscountUsageCard
        isEnterpriseOrgOwner={isEnterpriseOrgOwner}
        isCopilotPremiumUsageReportEnabled={isCopilotPremiumUsageReportEnabled}
        isLoadingDiscounts={isLoadingDiscounts}
        totalDiscount={totalDiscount}
        discountTargetAmounts={enabledProductDiscountTargetAmounts}
        discountStates={discountStates}
        isTokenBasedBillingEnabled={isTokenBasedBillingEnabled}
      />
      <DiscountForm
        customer={customer}
        enabledProducts={enabledProducts}
        onSuccess={handleSuccess}
        onError={handleError}
      />
    </>
  )
}
