import {useRoutePayload} from '@github-ui/react-core/use-route-payload'
import {announce} from '@github-ui/aria-live'
import Pluralize from 'pluralize'
import {useSearchParams} from '@github-ui/use-navigate'

import {Banner, Heading, LinkButton} from '@primer/react'
import {Octicon} from '@primer/react/deprecated'
import {Blankslate} from '@primer/react/experimental'
import {use, useState, useRef, useMemo, useCallback, useEffect} from 'react'
import {isFeatureEnabled} from '@github-ui/feature-flags'
import BudgetsTable from '../components/budget/BudgetsTable'
import BudgetsLoadingTable from '../components/budget/BudgetsLoadingTable'
import BudgetInfoBanner from '../components/budget/BudgetInfoBanner'
import IncludedUsageAlertsMenu from '../components/budget/IncludedUsageAlertsMenu'
import Layout from '../components/Layout'
import CopilotTrustTierLimitHitBanner, {
  type CopilotTrustTierLimitHitBannerProps,
} from '@github-ui/copilot-trust-tier-limit-hit-banner'
import useBudgetsPage from '../hooks/budget/use-budgets-page'
import useRoute from '../hooks/use-route'
import {NEW_BUDGET_ROUTE} from '../routes'
import {isOnTrial} from '../utils/business'

import {PageContext} from '../App'
import type {Budget} from '../types/budgets'
import type {AdminRole, Customer} from '../types/common'
import type {Product} from '../types/products'
import {GoalIcon, InfoIcon, MeterIcon, PlusIcon} from '@primer/octicons-react'
import {RequestState} from '../enums'
import {currentUserHasBudgetWritePermissions} from '../utils/permissions'
import useFilteredBudgets from '../hooks/budget/use-filtered-budgets'
import type {PricingDetails} from '../types/pricings'
import {
  BUDGETS_PAGE_SIZE,
  OWNER,
  BILLING_MANAGER,
  ENTERPRISE_ORG_OWNER,
  BUDGET_SCOPE_MULTI_USER_CUSTOMER,
} from '../constants'
import {BudgetType} from '../enums/budgets'
import styles from './BudgetsPage.module.css'

export interface BudgetsPagePayload {
  customer: Customer
  type: string
  budgets: Budget[]
  adminRoles: AdminRole[]
  enabledProducts: Product[]
  enabledSkus: PricingDetails[]
  helpUrl: string
  copilotIapSubscription: boolean
  includedUsageNotificationCustomer: boolean
  total_count: number
  consumedCopilotLicenses?: number
  multiScopeBudgetsEnabled?: boolean
  is_token_based_billing_enabled?: boolean
  copilot_trust_tier_limit_hit_banner?: CopilotTrustTierLimitHitBannerProps
}

const INCLUDED_USAGE_ALERTS_ENABLED_MESSAGE = 'Email alerts will be sent when included usage reaches 90% and 100%.'
const INCLUDED_USAGE_ALERTS_DISABLED_MESSAGE =
  'Email alerts will no longer be sent when included usage reaches 90% and 100%.'

const ENTERPRISE_SCOPES = [BudgetType.CUSTOMER, BudgetType.MULTI_USER_CUSTOMER]
const ORG_CUSTOMER_SCOPES = [BudgetType.CUSTOMER, BudgetType.MULTI_USER_CUSTOMER]
const ORG_NON_CUSTOMER_SCOPES = [BudgetType.USER, BudgetType.REPO]

const getCustomerTableHeaderText = (
  isOrganizationRoute: boolean,
  isUserRoute: boolean,
  isStafftoolsRoute: boolean,
  isEnterpriseRoute: boolean,
  isOnlyOrgAdmin: boolean = false,
  showCount: boolean = false,
  totalCount: number = 0,
): string => {
  let label: string
  if (isOnlyOrgAdmin) {
    label = 'Budgets'
  } else if (isUserRoute || (isStafftoolsRoute && !isEnterpriseRoute)) {
    // Calling these `Account` budgets for both orgs/users in stafftools
    label = 'Account budgets'
  } else if (isOrganizationRoute) {
    label = 'Organization budgets'
  } else {
    label = 'Enterprise budgets'
  }

  if (showCount) {
    return `${totalCount} ${label}`
  }
  return label
}

const getNonCustomerTableHeaderText = (
  showCount: boolean,
  totalCount: number,
  isServerPagination: boolean,
  filteredBudgetsLength: number,
): string => {
  if (isServerPagination) {
    if (showCount) {
      return `${totalCount} ${Pluralize('budget', totalCount)}`
    }
    return 'Budgets'
  }

  return `${filteredBudgetsLength} ${Pluralize('budget', filteredBudgetsLength)}`
}

export function BudgetsPage() {
  const payload = useRoutePayload<BudgetsPagePayload>()
  const {
    adminRoles,
    customer,
    enabledProducts,
    enabledSkus,
    helpUrl,
    copilotIapSubscription,
    includedUsageNotificationCustomer,
    consumedCopilotLicenses = 0,
    multiScopeBudgetsEnabled = false,
    is_token_based_billing_enabled: isTokenBasedBillingEnabled,
    copilot_trust_tier_limit_hit_banner: copilotTrustTierLimitHitBanner,
  } = payload

  const isDiscountThresholdNotificationEnabled = isFeatureEnabled('billing_discount_threshold_notification')
  const isUserLevelBudgetManagementEnabled = isFeatureEnabled('billing_user_level_budgets_manage')

  const [currentPage, setCurrentPage] = useState(1)
  const [currentScope, setCurrentScope] = useState<BudgetType | 'All'>('All')
  const [enterprisePage, setEnterprisePage] = useState(1)
  const [customerPage, setCustomerPage] = useState(1)
  const [includedUsageAlertsBanner, setIncludedUsageAlertsBanner] = useState<{show: boolean; enabled: boolean} | null>(
    null,
  )
  const enterpriseTableRef = useRef<HTMLDivElement>(null)
  const customerTableRef = useRef<HTMLDivElement>(null)
  const nonCustomerTableRef = useRef<HTMLDivElement>(null)

  const isPaginationEnabled = isFeatureEnabled('billing_ui_budget_pagination_enabled')
  const {isOrganizationRoute, isEnterpriseRoute, isUserRoute, isStafftoolsRoute} = use(PageContext)

  const isNonEnterpriseRoute = isOrganizationRoute || isUserRoute
  const shouldFetchEnterpriseBudgets = isPaginationEnabled && !isNonEnterpriseRoute
  const shouldFetchCustomerBudgets = isPaginationEnabled && (isOrganizationRoute || isUserRoute)
  const [searchParams, setSearchParams] = useSearchParams()

  const [showCreatedBanner, setShowCreatedBanner] = useState(
    () => searchParams.get('created') === 'true' && searchParams.get('type') != null,
  )
  const [createdBannerBudgetTypeText] = useState(() => searchParams.get('type') ?? '')

  // Strip banner params so a reload doesn't re-trigger the banner.
  useEffect(() => {
    if (!searchParams.has('created') && !searchParams.has('type')) return
    const next = new URLSearchParams(searchParams)
    next.delete('created')
    next.delete('type')
    setSearchParams(next, {replace: true})
  }, [searchParams, setSearchParams])

  // Hook for enterprise budgets only (when pagination is enabled and on enterprise routes)
  const {
    budgets: enterpriseBudgets,
    deleteBudgetFromPage: deleteEnterpriseBudget,
    requestState: enterpriseRequestState,
    totalCount: enterpriseTotalCount,
    hasNextPage: enterpriseHasNextPage,
    showCount: enterpriseShowCount,
  } = useBudgetsPage({
    page: enterprisePage,
    pageSize: BUDGETS_PAGE_SIZE,
    scope: multiScopeBudgetsEnabled ? undefined : BudgetType.ENTERPRISE,
    scopes: multiScopeBudgetsEnabled ? ENTERPRISE_SCOPES : undefined,
    noop: !shouldFetchEnterpriseBudgets,
  })

  // Hook for customer budgets only (when pagination is enabled and on org routes)
  const useOrgMultiScope = multiScopeBudgetsEnabled && isOrganizationRoute
  const {
    budgets: customerBudgetsFromHook,
    deleteBudgetFromPage: deleteCustomerBudget,
    requestState: customerRequestState,
    totalCount: customerTotalCount,
    hasNextPage: customerHasNextPage,
    showCount: customerShowCount,
  } = useBudgetsPage({
    page: customerPage,
    pageSize: BUDGETS_PAGE_SIZE,
    scope: useOrgMultiScope ? undefined : 'customer',
    scopes: useOrgMultiScope ? ORG_CUSTOMER_SCOPES : undefined,
    noop: !shouldFetchCustomerBudgets,
  })

  const excludeScope = useMemo(() => {
    if (multiScopeBudgetsEnabled) return undefined
    if (!isPaginationEnabled || currentScope !== 'All') {
      return undefined
    }
    if (!isNonEnterpriseRoute) {
      return 'enterprise'
    }
    return undefined
  }, [multiScopeBudgetsEnabled, isPaginationEnabled, currentScope, isNonEnterpriseRoute])

  const excludeScopes = useMemo(() => {
    if (!multiScopeBudgetsEnabled) return undefined
    if (!isPaginationEnabled || currentScope !== 'All') return undefined
    if (!isNonEnterpriseRoute) {
      return ENTERPRISE_SCOPES
    }
    return undefined
  }, [multiScopeBudgetsEnabled, isPaginationEnabled, currentScope, isNonEnterpriseRoute])

  const nonCustomerScope = useMemo(() => {
    if (useOrgMultiScope) return undefined
    if (isPaginationEnabled && (isOrganizationRoute || isUserRoute)) {
      return BudgetType.REPO
    }
    return !isPaginationEnabled ? currentScope : currentScope === 'All' ? undefined : currentScope
  }, [useOrgMultiScope, isPaginationEnabled, isOrganizationRoute, isUserRoute, currentScope])

  const nonCustomerScopes = useMemo(() => {
    if (useOrgMultiScope) return ORG_NON_CUSTOMER_SCOPES
    return undefined
  }, [useOrgMultiScope])

  // Hook for non-enterprise/non-customer budgets
  const {
    budgets: nonEnterpriseBudgets,
    deleteBudgetFromPage: deleteNonEnterpriseBudget,
    requestState: nonEnterpriseRequestState,
    totalCount: nonEnterpriseTotalCount,
    hasNextPage: nonEnterpriseHasNextPage,
    showCount: nonEnterpriseShowCount,
  } = useBudgetsPage({
    page: currentPage,
    pageSize: BUDGETS_PAGE_SIZE,
    scope: nonCustomerScope,
    scopes: nonCustomerScopes,
    excludeScope,
    excludeScopes,
  })

  // Use the appropriate budgets based on pagination flag
  const budgets = nonEnterpriseBudgets
  const deleteBudgetFromPage = deleteNonEnterpriseBudget
  const requestState = nonEnterpriseRequestState
  const totalCount = nonEnterpriseTotalCount
  const hasNextPage = nonEnterpriseHasNextPage

  // For pagination-enabled org/user routes, use separate hook data; otherwise filter budgets
  const {customerBudgets: filteredCustomerBudgets, nonCustomerBudgets: filteredNonCustomerBudgets} = useFilteredBudgets(
    budgets,
    isOrganizationRoute,
    isUserRoute,
    isStafftoolsRoute || isUserLevelBudgetManagementEnabled,
  )

  const customerBudgets = useMemo(
    () =>
      isPaginationEnabled && (isOrganizationRoute || isUserRoute)
        ? customerBudgetsFromHook
        : isPaginationEnabled && isEnterpriseRoute
          ? [] // MultiUserCustomer budgets are shown in the enterprise table on enterprise routes
          : filteredCustomerBudgets,
    [
      isPaginationEnabled,
      isOrganizationRoute,
      isUserRoute,
      isEnterpriseRoute,
      customerBudgetsFromHook,
      filteredCustomerBudgets,
    ],
  )

  // When pagination is enabled on enterprise routes, filter out universal budgets from non-customer budgets
  // since they're shown in the enterprise budgets section
  const nonCustomerBudgets = useMemo(() => {
    if (isPaginationEnabled) {
      if (isEnterpriseRoute && !multiScopeBudgetsEnabled) {
        return budgets.filter(b => b.targetType !== BUDGET_SCOPE_MULTI_USER_CUSTOMER)
      }
      return budgets
    }
    return filteredNonCustomerBudgets
  }, [isPaginationEnabled, isEnterpriseRoute, multiScopeBudgetsEnabled, budgets, filteredNonCustomerBudgets])

  // On enterprise routes with pagination, merge MultiUserCustomer budgets into the enterprise table
  // since they are considered enterprise-level budgets. Deduplicate in case the enterprise hook
  // already returns some MultiUserCustomer budgets.
  // When multiScopeBudgetsEnabled, the server already includes them — no merge needed.
  const allEnterpriseBudgets = useMemo(() => {
    if (!isPaginationEnabled || !isEnterpriseRoute) return enterpriseBudgets
    if (multiScopeBudgetsEnabled) return enterpriseBudgets
    const enterpriseUuids = new Set(enterpriseBudgets.map(b => b.uuid))
    const newMultiUserCustomerBudgets = budgets.filter(
      b => b.targetType === BUDGET_SCOPE_MULTI_USER_CUSTOMER && !enterpriseUuids.has(b.uuid),
    )
    return [...enterpriseBudgets, ...newMultiUserCustomerBudgets]
  }, [isPaginationEnabled, isEnterpriseRoute, multiScopeBudgetsEnabled, enterpriseBudgets, budgets])

  // Adjust enterprise total count to include new MultiUserCustomer budgets not already counted
  // When multiScopeBudgetsEnabled, the server count is already correct.
  const adjustedEnterpriseTotalCount = useMemo(() => {
    if (!isPaginationEnabled || !isEnterpriseRoute) return enterpriseTotalCount
    if (multiScopeBudgetsEnabled) return enterpriseTotalCount
    const enterpriseUuids = new Set(enterpriseBudgets.map(b => b.uuid))
    const newMultiUserCustomerCount = budgets.filter(
      b => b.targetType === BUDGET_SCOPE_MULTI_USER_CUSTOMER && !enterpriseUuids.has(b.uuid),
    ).length
    return enterpriseTotalCount + newMultiUserCustomerCount
  }, [
    isPaginationEnabled,
    isEnterpriseRoute,
    multiScopeBudgetsEnabled,
    enterpriseTotalCount,
    enterpriseBudgets,
    budgets,
  ])

  // Adjust non-enterprise total count to exclude MultiUserCustomer budgets (they're in the enterprise table)
  // When multiScopeBudgetsEnabled, the server count is already correct.
  const adjustedNonEnterpriseTotalCount = useMemo(() => {
    if (!isPaginationEnabled || !isEnterpriseRoute) return totalCount
    if (multiScopeBudgetsEnabled) return totalCount
    const multiUserCustomerCount = budgets.filter(b => b.targetType === BUDGET_SCOPE_MULTI_USER_CUSTOMER).length
    return totalCount - multiUserCustomerCount
  }, [isPaginationEnabled, isEnterpriseRoute, multiScopeBudgetsEnabled, totalCount, budgets])

  // Combined delete function for the enterprise table that routes to the correct hook
  const deleteFromEnterpriseTable = useCallback(
    (uuid: string) => {
      if (enterpriseBudgets.some(b => b.uuid === uuid)) {
        deleteEnterpriseBudget(uuid)
      } else {
        deleteBudgetFromPage(uuid)
      }
    },
    [enterpriseBudgets, deleteEnterpriseBudget, deleteBudgetFromPage],
  )

  const trialCustomer = isOnTrial(customer.plan)
  const hasBudgetWritePermissions = currentUserHasBudgetWritePermissions(
    adminRoles,
    isEnterpriseRoute,
    isStafftoolsRoute,
    trialCustomer,
  )
  const budgetsDocsUrl = `${helpUrl}/early-access/billing/billing-private-beta#using-budgets-and-alerts`

  // Computed values
  const budgetsLength = useMemo(() => {
    const premiumRequestsBudgets = 0
    return Math.max(
      0,
      customerBudgets.length +
        nonCustomerBudgets.length +
        (isPaginationEnabled ? allEnterpriseBudgets.length : 0) -
        premiumRequestsBudgets,
    )
  }, [customerBudgets.length, nonCustomerBudgets.length, allEnterpriseBudgets.length, isPaginationEnabled])

  const isOnlyOrgAdmin =
    !adminRoles.includes(OWNER) && !adminRoles.includes(BILLING_MANAGER) && adminRoles.includes(ENTERPRISE_ORG_OWNER)

  const enterpriseTableHeaderText = useMemo(
    () =>
      getCustomerTableHeaderText(
        isOrganizationRoute,
        isUserRoute,
        isStafftoolsRoute,
        isEnterpriseRoute,
        isOnlyOrgAdmin,
        enterpriseShowCount,
        adjustedEnterpriseTotalCount,
      ),
    [
      isOrganizationRoute,
      isUserRoute,
      isStafftoolsRoute,
      isEnterpriseRoute,
      isOnlyOrgAdmin,
      enterpriseShowCount,
      adjustedEnterpriseTotalCount,
    ],
  )

  const customerTableHeaderText = useMemo(
    () =>
      getCustomerTableHeaderText(
        isOrganizationRoute,
        isUserRoute,
        isStafftoolsRoute,
        isEnterpriseRoute,
        isOnlyOrgAdmin,
        customerShowCount,
        customerTotalCount,
      ),
    [
      isOrganizationRoute,
      isUserRoute,
      isStafftoolsRoute,
      isEnterpriseRoute,
      isOnlyOrgAdmin,
      customerShowCount,
      customerTotalCount,
    ],
  )

  const customerTableLabel = useMemo(
    () =>
      getCustomerTableHeaderText(
        isOrganizationRoute,
        isUserRoute,
        isStafftoolsRoute,
        isEnterpriseRoute,
        isOnlyOrgAdmin,
      ),
    [isOrganizationRoute, isUserRoute, isStafftoolsRoute, isEnterpriseRoute, isOnlyOrgAdmin],
  )

  const nonCustomerTableHeaderText = useMemo(
    () =>
      getNonCustomerTableHeaderText(
        nonEnterpriseShowCount && !isOnlyOrgAdmin,
        adjustedNonEnterpriseTotalCount,
        isPaginationEnabled,
        nonCustomerBudgets.length,
      ),
    [
      nonEnterpriseShowCount,
      isOnlyOrgAdmin,
      adjustedNonEnterpriseTotalCount,
      isPaginationEnabled,
      nonCustomerBudgets.length,
    ],
  )

  const {path: newBudgetPath} = useRoute(NEW_BUDGET_ROUTE)

  const isInitialEmptyState = useMemo(() => {
    if (budgetsLength > 0 || isStafftoolsRoute || requestState !== RequestState.IDLE) {
      return false
    }

    if (isPaginationEnabled) {
      if (enterpriseRequestState !== RequestState.IDLE || customerRequestState !== RequestState.IDLE) {
        return false
      }
    }

    return currentPage === 1 && currentScope === 'All'
  }, [
    budgetsLength,
    isStafftoolsRoute,
    requestState,
    enterpriseRequestState,
    customerRequestState,
    isPaginationEnabled,
    currentPage,
    currentScope,
  ])

  const isFilterActive = currentScope !== 'All'
  const hasBudgetsOrFilteredResults =
    (adjustedNonEnterpriseTotalCount ?? 0) > 0 || nonCustomerBudgets.length > 0 || isFilterActive
  const hasCustomerBudgetsOrFilteredResults = (customerTotalCount ?? 0) > 0 || customerBudgets.length > 0

  // Conditions for showing enterprise table
  const shouldShowEnterpriseLoading = isPaginationEnabled && enterpriseRequestState === RequestState.LOADING
  const shouldShowEnterpriseTable =
    isPaginationEnabled && enterpriseRequestState === RequestState.IDLE && allEnterpriseBudgets.length > 0

  // Conditions for showing customer table (org/user routes with pagination)
  const shouldShowCustomerLoading =
    isPaginationEnabled && (isOrganizationRoute || isUserRoute) && customerRequestState === RequestState.LOADING
  const shouldShowCustomerTable =
    isPaginationEnabled && (isOrganizationRoute || isUserRoute)
      ? customerRequestState === RequestState.IDLE &&
        (customerBudgets.length > 0 || hasCustomerBudgetsOrFilteredResults)
      : requestState === RequestState.IDLE && customerBudgets.length > 0

  // Conditions for showing non-customer/non-enterprise tables
  const shouldShowNonEnterpriseLoading = requestState === RequestState.LOADING
  const shouldShowNonCustomerTable =
    requestState === RequestState.IDLE &&
    (nonCustomerBudgets.length > 0 ||
      (isPaginationEnabled && (isEnterpriseRoute || isOrganizationRoute || isUserRoute) && hasBudgetsOrFilteredResults))

  const hasPreviousPage = currentPage > 1
  const enterpriseHasPreviousPage = enterprisePage > 1
  const customerHasPreviousPage = customerPage > 1

  const getInitialBudgetsText = useCallback(() => {
    const baseText = 'Create budgets to track your spending on products like Actions and Copilot'
    return isUserRoute ? `${baseText}.` : `${baseText} for a single repository or the entire organization.`
  }, [isUserRoute])

  const handlePageChange = useCallback((page: number) => {
    setCurrentPage(page)
    nonCustomerTableRef.current?.scrollIntoView({behavior: 'smooth', block: 'start'})
  }, [])

  const handleEnterprisePageChange = useCallback((page: number) => {
    setEnterprisePage(page)
    enterpriseTableRef.current?.scrollIntoView({behavior: 'smooth', block: 'start'})
  }, [])

  const handleCustomerPageChange = useCallback((page: number) => {
    setCustomerPage(page)
    customerTableRef.current?.scrollIntoView({behavior: 'smooth', block: 'start'})
  }, [])

  const handleScopeChange = useCallback((scope: BudgetType | 'All') => {
    setCurrentScope(scope)
    setCurrentPage(1)
  }, [])

  const handleIncludedUsageAlertsChange = useCallback((enabled: boolean) => {
    setIncludedUsageAlertsBanner({show: true, enabled})
  }, [])

  // Announce banner content to screen readers when it appears
  useEffect(() => {
    if (includedUsageAlertsBanner?.show) {
      const message = includedUsageAlertsBanner.enabled
        ? `Email notifications turned on. ${INCLUDED_USAGE_ALERTS_ENABLED_MESSAGE}`
        : `Email notifications turned off. ${INCLUDED_USAGE_ALERTS_DISABLED_MESSAGE}`
      announce(message)
    }
  }, [includedUsageAlertsBanner])

  return (
    <Layout>
      {showCreatedBanner && (
        <Banner
          title="Budget created"
          hideTitle
          variant="success"
          onDismiss={() => setShowCreatedBanner(false)}
          className={styles.createdBanner}
          data-testid="budget-created-banner"
        >
          {isTokenBasedBillingEnabled
            ? `${createdBannerBudgetTypeText} budget for AI credits was successfully created. Budget usage will appear on this page once your users begin consuming billable usage.`
            : `${createdBannerBudgetTypeText} budget for premium requests was successfully created. Budget usage will appear on this page once your users begin consuming billable usage.`}
        </Banner>
      )}
      <header className="Subhead">
        <Heading as="h1" className={`Subhead-heading ${styles.pageHeading}`}>
          Budgets and alerts
        </Heading>
        <div className="Subhead-actions">
          <div className={styles.headerActions}>
            {isDiscountThresholdNotificationEnabled && (
              <IncludedUsageAlertsMenu
                initialEnabled={includedUsageNotificationCustomer}
                onSettingChange={handleIncludedUsageAlertsChange}
              />
            )}

            {hasBudgetWritePermissions &&
              (isDiscountThresholdNotificationEnabled ? (
                <LinkButton href={newBudgetPath} variant="primary" leadingVisual={PlusIcon}>
                  New budget
                </LinkButton>
              ) : (
                <LinkButton href={newBudgetPath} variant="primary">
                  New budget
                </LinkButton>
              ))}
          </div>
        </div>
      </header>
      {includedUsageAlertsBanner?.show && (
        <Banner
          data-testid="included-usage-alerts-banner"
          title="Email notification setting updated"
          hideTitle
          className={styles.includedUsageAlertsBanner}
          variant="success"
          onDismiss={() => setIncludedUsageAlertsBanner(null)}
        >
          {includedUsageAlertsBanner.enabled
            ? INCLUDED_USAGE_ALERTS_ENABLED_MESSAGE
            : INCLUDED_USAGE_ALERTS_DISABLED_MESSAGE}
        </Banner>
      )}
      {copilotTrustTierLimitHitBanner && (
        <div className="tmp-mb-3">
          <CopilotTrustTierLimitHitBanner {...copilotTrustTierLimitHitBanner} />
        </div>
      )}
      <BudgetInfoBanner />
      {trialCustomer ? (
        <div className="text-center">
          <Blankslate border>
            <Blankslate.Visual>
              <GoalIcon size={24} />
            </Blankslate.Visual>
            <Blankslate.Heading>Track spending using budgets</Blankslate.Heading>
            <Blankslate.Description>
              <span>
                You can create budgets to track your spending on products like Actions and Copilot for an organization,
                repository, cost center or the entire enterprise.
              </span>
              <br />
              <br />
              <span>
                <InfoIcon size={16} /> This is a paid feature and is not included as part of your trial.
              </span>
            </Blankslate.Description>
            <Blankslate.SecondaryAction href={budgetsDocsUrl}>Learn more about budgets</Blankslate.SecondaryAction>
          </Blankslate>
        </div>
      ) : (
        <>
          {isInitialEmptyState ? (
            <div className={styles.emptyStateContainer}>
              <div className={styles.iconContainer}>
                <Octicon icon={MeterIcon} size={24} />
              </div>
              <div className={styles.emptyStateContentContainer}>
                <Heading as="h1" className={styles.emptyStateHeading}>
                  No budgets created
                </Heading>
                <p className={styles.emptyStateDescription}>{getInitialBudgetsText()}</p>
              </div>
              {hasBudgetWritePermissions && (
                <LinkButton href={newBudgetPath} variant="primary">
                  New budget
                </LinkButton>
              )}
            </div>
          ) : (
            <>
              {/* Enterprise budgets table */}
              {shouldShowEnterpriseLoading && (
                <div className={styles.tableSection}>
                  <BudgetsLoadingTable
                    isCustomerTable
                    customerTableLabel={customerTableLabel}
                    isEnterpriseRoute={isEnterpriseRoute}
                    showScopeSelector={false}
                  />
                </div>
              )}

              {shouldShowEnterpriseTable && (
                <div ref={enterpriseTableRef} className={styles.tableSection}>
                  <BudgetsTable
                    budgets={allEnterpriseBudgets}
                    deleteBudget={deleteFromEnterpriseTable}
                    enabledProducts={enabledProducts}
                    enabledSkus={enabledSkus}
                    isCustomerTable
                    tableHeaderText={enterpriseTableHeaderText}
                    isEnterpriseRoute={isEnterpriseRoute}
                    hasBudgetWritePermissions={hasBudgetWritePermissions}
                    copilotIapSubscription={copilotIapSubscription}
                    isServerPagination={isPaginationEnabled}
                    totalCount={adjustedEnterpriseTotalCount}
                    currentPage={enterprisePage}
                    onPageChange={handleEnterprisePageChange}
                    currentScope="All"
                    onScopeChange={() => {}}
                    hasNextPage={enterpriseHasNextPage}
                    hasPreviousPage={enterpriseHasPreviousPage}
                    consumedCopilotLicenses={consumedCopilotLicenses}
                    isTokenBasedBillingEnabled={isTokenBasedBillingEnabled}
                  />
                </div>
              )}

              {/* Non-enterprise budgets tables */}
              {/* Customer budgets table (org/user routes with pagination) */}
              {shouldShowCustomerLoading && (
                <div className={styles.tableSection}>
                  <BudgetsLoadingTable
                    isCustomerTable
                    customerTableLabel={customerTableLabel}
                    isEnterpriseRoute={isEnterpriseRoute}
                  />
                </div>
              )}

              {shouldShowCustomerTable && (
                <div
                  ref={isPaginationEnabled && (isOrganizationRoute || isUserRoute) ? customerTableRef : undefined}
                  className={styles.tableSection}
                >
                  <BudgetsTable
                    budgets={customerBudgets}
                    deleteBudget={
                      isPaginationEnabled && (isOrganizationRoute || isUserRoute)
                        ? deleteCustomerBudget
                        : deleteBudgetFromPage
                    }
                    enabledProducts={enabledProducts}
                    enabledSkus={enabledSkus}
                    isCustomerTable
                    tableHeaderText={customerTableHeaderText}
                    isEnterpriseRoute={isEnterpriseRoute}
                    hasBudgetWritePermissions={hasBudgetWritePermissions}
                    copilotIapSubscription={copilotIapSubscription}
                    isServerPagination={isPaginationEnabled}
                    totalCount={
                      isPaginationEnabled && (isOrganizationRoute || isUserRoute) ? customerTotalCount : totalCount
                    }
                    currentPage={
                      isPaginationEnabled && (isOrganizationRoute || isUserRoute) ? customerPage : currentPage
                    }
                    onPageChange={
                      isPaginationEnabled && (isOrganizationRoute || isUserRoute)
                        ? handleCustomerPageChange
                        : handlePageChange
                    }
                    hasNextPage={
                      isPaginationEnabled && (isOrganizationRoute || isUserRoute) ? customerHasNextPage : hasNextPage
                    }
                    hasPreviousPage={
                      isPaginationEnabled && (isOrganizationRoute || isUserRoute)
                        ? customerHasPreviousPage
                        : hasPreviousPage
                    }
                    consumedCopilotLicenses={consumedCopilotLicenses}
                    isTokenBasedBillingEnabled={isTokenBasedBillingEnabled}
                  />
                </div>
              )}

              {/* Non-customer/non-enterprise budgets loading */}
              {shouldShowNonEnterpriseLoading && isPaginationEnabled && (
                <div className={styles.tableSection}>
                  <BudgetsLoadingTable
                    isCustomerTable={false}
                    customerTableLabel={customerTableLabel}
                    isEnterpriseRoute={isEnterpriseRoute}
                  />
                </div>
              )}

              {shouldShowNonCustomerTable && (
                <div ref={nonCustomerTableRef} className={styles.tableSection}>
                  <BudgetsTable
                    budgets={nonCustomerBudgets}
                    deleteBudget={deleteBudgetFromPage}
                    enabledProducts={enabledProducts}
                    enabledSkus={enabledSkus}
                    isEnterpriseRoute={isEnterpriseRoute}
                    hasBudgetWritePermissions={hasBudgetWritePermissions}
                    copilotIapSubscription={copilotIapSubscription}
                    isServerPagination={isPaginationEnabled}
                    totalCount={adjustedNonEnterpriseTotalCount}
                    currentPage={currentPage}
                    onPageChange={handlePageChange}
                    currentScope={currentScope}
                    onScopeChange={handleScopeChange}
                    hasNextPage={hasNextPage}
                    hasPreviousPage={hasPreviousPage}
                    tableHeaderText={nonCustomerTableHeaderText}
                    consumedCopilotLicenses={consumedCopilotLicenses}
                    isTokenBasedBillingEnabled={isTokenBasedBillingEnabled}
                  />
                </div>
              )}
            </>
          )}
        </>
      )}
    </Layout>
  )
}
