import {Details, Link, ProgressBar, Tooltip, useDetails, useResponsiveValue} from '@primer/react'
import {useMemo} from 'react'
import {Octicon} from '@primer/react/deprecated'
import {ChevronDownIcon, ChevronRightIcon} from '@primer/octicons-react'
import type {UsageTableDataCell, UsageTableData, GroupSelection} from '../../../types/usage'
import {parseFormattedNumber} from '../../../utils/usage'

import sharedStyles from '../UsageTable/shared.module.css'
import rowStyles from '../UsageTable/UsageTableRow.module.css'
import styles from './AIUsageTableRow.module.css'
import tableStyles from './AIUsageTable.module.css'
import AIUsageSubTable from './AIUsageSubTable'
import {UsageGrouping} from '../../../enums'
import {GitHubAvatar} from '@github-ui/github-avatar'

interface AIUsageTableRowProps {
  cells: UsageTableDataCell[]
  groupBy?: GroupSelection
  subtable?: UsageTableData
  isSubtable: boolean
  showProgressBar?: boolean
  premiumRequestsQuota?: string
}

export default function AIUsageTableRow({
  cells,
  groupBy,
  subtable,
  isSubtable,
  showProgressBar,
  premiumRequestsQuota,
}: AIUsageTableRowProps) {
  const {getDetailsProps, open} = useDetails({closeOnOutsideClick: false})
  const expandable = subtable != null && subtable.rows.length > 0

  const consumedIncludedRequestsValue = cells[1]?.value

  const quotaNumber = parseFormattedNumber(premiumRequestsQuota || '0')
  const consumedNumber = parseFormattedNumber(consumedIncludedRequestsValue || '0')

  const progressPercentage = useMemo(() => {
    if (isNaN(consumedNumber) || isNaN(quotaNumber)) {
      return 0
    }
    if (quotaNumber === 0) {
      return 100
    }
    return Math.min((consumedNumber / quotaNumber) * 100, 100)
  }, [consumedNumber, quotaNumber])

  const consumedValue = consumedIncludedRequestsValue || '0'
  const quotaValue = premiumRequestsQuota || '0'
  const progressDisplayValueLong = `${consumedValue}/${quotaValue}`
  const progressDisplayValue = useResponsiveValue(
    {regular: progressDisplayValueLong, narrow: consumedValue},
    progressDisplayValueLong,
  ) as string
  const getRowContent = (): React.ReactElement => {
    return (
      <div className={sharedStyles.trStyle}>
        {isSubtable ? (
          <>
            <div className={tableStyles.expandableIconSpacer} />
            <div className={`${styles.identifierCell} ${sharedStyles.borderTop} pl-0`} data-testid="identifier-td">
              {getFirstColumnContent()}
            </div>
          </>
        ) : (
          <div className={`${styles.identifierCell} d-flex flex-items-center`} data-testid="identifier-td">
            {expandable && (
              <Tooltip text={open ? 'Hide Usage Breakdown' : 'Show Usage Breakdown'}>
                <Details {...getDetailsProps()}>
                  <summary
                    className="tmp-pr-4"
                    aria-label={open ? 'Hide Usage Breakdown' : 'Show Usage Breakdown'}
                    data-testid={'usage-details'}
                  >
                    <Octicon icon={open ? ChevronDownIcon : ChevronRightIcon} />
                  </summary>
                </Details>
              </Tooltip>
            )}
            <div>{getFirstColumnContent()}</div>
          </div>
        )}

        <div
          className={`${styles.fixedWidthCell} ${styles.includedRequestsCell} ${
            isSubtable ? sharedStyles.borderTop : styles.mutedText
          }`}
          data-testid="included-requests-td"
        >
          {showProgressBar && quotaNumber > 0 ? (
            <div className={styles.progressBarContainer}>
              <span className={styles.progressText}>{progressDisplayValue}</span>
              <div className={styles.progressBar}>
                <ProgressBar
                  aria-label="Included premium requests progress"
                  aria-valuetext={`${progressDisplayValue} premium requests used`}
                  bg="accent.emphasis"
                  progress={progressPercentage}
                  barSize="small"
                />
              </div>
            </div>
          ) : (
            <span>{cells[1]?.value}</span>
          )}
        </div>
        <div
          className={`${styles.fixedWidthCell} ${isSubtable ? sharedStyles.borderTop : styles.mutedText}`}
          data-testid="billing-requests-td"
        >
          <span>{cells[2]?.value}</span>
        </div>
        <div
          className={`${styles.fixedWidthCell} ${isSubtable ? sharedStyles.borderTop : styles.mutedText}`}
          data-testid="gross-amount-td"
        >
          <span>{cells[3]?.value}</span>
        </div>
        <div
          className={`${styles.fixedWidthCell} ${isSubtable ? sharedStyles.borderTop : 'text-bold'}`}
          data-testid="billed-amount-td"
        >
          <span>{cells[4]?.value}</span>
        </div>
      </div>
    )
  }

  const useRichRowName = (groupBy?.type === UsageGrouping.ORG || groupBy?.type === UsageGrouping.USER) && cells[0]?.slug

  const getFirstColumnContent = (): React.ReactElement => {
    if (useRichRowName && cells[0]?.avatarSrc) {
      return (
        <Link href={`/${cells[0]?.slug}`} target="_blank" className={rowStyles.columnAvatarStyle}>
          {cells[0]?.avatarSrc && (
            <GitHubAvatar square src={cells[0]?.avatarSrc} size={20} className="mr-2 flex-shrink-0" />
          )}
          {cells[0]?.name}
        </Link>
      )
    } else {
      return <span>{useRichRowName && cells[0]?.name ? cells[0]?.name : cells[0]?.value}</span>
    }
  }

  return (
    <div className={isSubtable ? '' : sharedStyles.borderTop}>
      {getRowContent()}
      {subtable && <div className={sharedStyles.trStyle}>{open && <AIUsageSubTable subtable={subtable} />}</div>}
    </div>
  )
}
