import {formatQuantityDisplay, getBilledAmount} from '../../../utils/usage'
import {clsx} from 'clsx'

import type {ProductUsageLineItem} from '../../../types/usage'
import {formatMoneyDisplay} from '../../../utils/money'
import {isLicensedSkuWithDailyEmissions} from '../../../utils'
import sharedStyles from './shared.module.css'
import styles from './UsageSubTable.module.css'

interface Props {
  data: ProductUsageLineItem[]
}

export default function UsageSubTable({data}: Props) {
  // sort by SKU name to preserve order of row entries between sub table rows
  const sortedData = data.sort((a, b) => {
    return a.friendlySkuName.localeCompare(b.friendlySkuName)
  })

  const getRowCost = (row: ProductUsageLineItem) => {
    // for licensed products with daily emissions, we show a prorated cost equal to the monthly cost / days in the month of usage
    if (isLicensedSkuWithDailyEmissions(row) && row.dailyLicenseCost) {
      return row.dailyLicenseCost
    } else return row.appliedCostPerQuantity
  }

  return (
    <div className={sharedStyles.tableStyle} data-testid="usage-sub-table">
      <div className={sharedStyles.trStyle}>
        <div className={styles.spacer} />
        <div className={clsx(sharedStyles.identifierCell, styles.subtleText, styles.subTableIdentifierCell)}>SKU</div>
        <div className={clsx(sharedStyles.fixedWidthCell, styles.subtleText)}>Units</div>
        <div className={clsx(sharedStyles.fixedWidthCell, styles.subtleText)}>Price/unit</div>
        <div className={clsx(sharedStyles.fixedWidthCell, styles.subtleText)}>Gross amount</div>
        <div className={clsx(sharedStyles.fixedWidthCell, styles.subtleText)}>Billed amount</div>
      </div>
      <div>
        {sortedData.map(row => {
          return (
            <div className={sharedStyles.trStyle} key={`sub-table-${row.product}-${row.sku}-${row.usageAt}`}>
              <div className={styles.spacer} />
              <div
                className={clsx(sharedStyles.borderTop, sharedStyles.identifierCell, styles.subTableIdentifierCell)}
                data-testid="sub-sku-td"
              >
                {row.friendlySkuName ?? row.sku}
                {row.sku === 'actions_cache_storage' && (
                  <p className="text-small color-fg-muted">Additional paid usage</p>
                )}
              </div>
              <div className={clsx(sharedStyles.fixedWidthCell, sharedStyles.borderTop)} data-testid="sub-quantity-td">
                {formatQuantityDisplay(row, 2)}
              </div>
              <div
                className={clsx(sharedStyles.fixedWidthCell, sharedStyles.borderTop)}
                data-testid="sub-applied-cost-per-quantity-td"
              >
                {formatMoneyDisplay(getRowCost(row), 6)}
              </div>
              <div
                className={clsx(sharedStyles.fixedWidthCell, sharedStyles.borderTop)}
                data-testid="sub-gross-amount-td"
              >
                {formatMoneyDisplay(row.billedAmount)}
              </div>
              <div
                className={clsx(sharedStyles.fixedWidthCell, sharedStyles.borderTop)}
                data-testid="sub-billed-amount-td"
              >
                {getBilledAmount(row.totalAmount)}
              </div>
            </div>
          )
        })}
      </div>
    </div>
  )
}
