export function filterbyEnabledProducts(enabledProducts: EnabledProduct[]): (discount: DiscountState) => boolean {
  return function (discount: DiscountState) {
    const enabled_sku_targets: string[] = []
    for (const product of enabledProducts) {
      const productSkus = [...PRODUCT_DISCOUNT_SKU_MAP[product.name]]
      // TODO: Remove after public preview, filters out actions_custom_image_storage sku from target type (hiding it)
      const filteredSkus = !isFeatureEnabled('actions_custom_images_storage_billing_ui_visibility')
        ? productSkus.filter(sku => !STANDARD_ACTIONS_CUSTOM_IMAGE_STORAGE_SKUS.includes(sku))
        : productSkus

      enabled_sku_targets.push(...filteredSkus)
    }
    for (const target of discount.targets) {
      if (target.type === 'SkuDiscount') {
        if (enabled_sku_targets.includes(target.id)) {
          return true
        } else {
          return false
        }
      } else {
        break
      }
    }
    return true
  }
}

