import type {BudgetThresholdsSummary} from '../types/budgets'

export interface BudgetSegments {
  noUsage: number
  belowThreshold: number
  nearLimit: number
  atOrAboveLimit: number
}

/**
 * Derive the four display segments from the proto threshold map and total license count.
 *
 * Proto map keys: 0 (0–74% usage), 75, 90, 100
 *
 * - Gray  : consumedCopilotLicenses − sum of all threshold buckets – users with no usage
 * - Blue  : map[0]  – users between 0–74 % of budget used
 * - Yellow: map[75] + map[90]  – users between 75–99 %
 * - Red   : map[100]  – users at or above 100 %
 */
export function deriveSegments(
  consumedCopilotLicenses: number,
  budgetThresholdsSummary?: BudgetThresholdsSummary,
): BudgetSegments {
  const at0 = budgetThresholdsSummary?.[0] ?? 0
  const at75 = budgetThresholdsSummary?.[75] ?? 0
  const at90 = budgetThresholdsSummary?.[90] ?? 0
  const at100 = budgetThresholdsSummary?.[100] ?? 0

  const thresholdTotal = at0 + at75 + at90 + at100
  const noUsage = Math.max(consumedCopilotLicenses - thresholdTotal, 0)
  const belowThreshold = at0
  const nearLimit = at75 + at90
  const atOrAboveLimit = at100

  return {noUsage, belowThreshold, nearLimit, atOrAboveLimit}
}
