import {useRoutePayload} from '@github-ui/react-core/use-route-payload'
import {useFeatureFlag} from '@github-ui/react-core/use-feature-flag'
import {BriefcaseIcon} from '@primer/octicons-react'
import {Link, LinkButton, Banner, Heading, UnderlineNav} from '@primer/react'
import {clsx} from 'clsx'
import {Dialog} from '@primer/react/experimental'
import {Octicon} from '@primer/react/deprecated'
import {use, useCallback, useRef, useState, useEffect} from 'react'
import {useLocation} from '@github-ui/react-router'
import {useNavigate, useSearchParams} from '@github-ui/use-navigate'
import Pluralize from 'pluralize'
import {announce} from '@github-ui/aria-live'

import {PageContext, ReloadContext} from '../App'
import CostCentersTable from '../components/cost_centers/CostCentersTable'
import CostCentersLoadingTable from '../components/cost_centers/CostCentersLoadingTable'
import CostCenterBanner from '../components/cost_centers/CostCenterBanner'
import ReassignedResources from '../components/cost_centers/ReassignedResources'
import Layout from '../components/Layout'
import useRoute from '../hooks/use-route'
import useCostCentersPageWithLoading from '../hooks/cost_centers/use-cost-centers-page-with-loading'
import {COST_CENTERS_ROUTE, NEW_COST_CENTER_ROUTE} from '../routes'
import styles from './CostCentersPage.module.css'
import {RequestState} from '../enums'
import type {GetAllCostCentersResponse, ReassignedResource} from '../types/cost-centers'
import CostCenterNotification from '../components/cost_centers/CostCenterNotification'

export const CostCenterTabs = {
  Active: 'active',
  Deleted: 'deleted',
} as const

export type CostCenterTabs = (typeof CostCenterTabs)[keyof typeof CostCenterTabs]

export function CostCentersPage() {
  const payload = useRoutePayload<GetAllCostCentersResponse>()
  const {
    activeCostCenters: initialActiveCostCenters,
    archivedCostCenters: initialArchivedCostCenters,
    hasNextPage: initialHasNextPage,
    hasUserScopedCostCenters: initialHasUserScopedCostCenters,
    orgOwnerAccessDenied,
    billingAddCostCenterDescription = false,
    enterpriseTeamsEnabled = false,
    totalCount,
  } = payload
  const [searchParams] = useSearchParams()
  const [resources, setResources] = useState<ReassignedResource[]>([])
  const [showBanner, setShowBanner] = useState(false)
  const [bannerMessage, setBannerMessage] = useState('')
  const [costCenterName, setCostCenterName] = useState('')
  const [bannerType, setBannerType] = useState<'success' | 'critical'>('success')
  const isStafftoolsRoute = use(PageContext).isStafftoolsRoute
  const {reloadKey} = use(ReloadContext)
  /* eslint-disable-next-line @github-ui/github-monorepo/no-use-feature-flags --
     TODO: Migrate to isFeatureEnabled from @github-ui/feature-flags. See
     https://thehub.github.com/epd/engineering/dev-practicals/frontend/react/data-router/migration/app-payload-deprecation/ */
  const billingCostCentersUIPagination = useFeatureFlag('billing_cost_centers_ui_pagination_enabled')
  /* eslint-disable-next-line @github-ui/github-monorepo/no-use-feature-flags --
     TODO: Migrate to isFeatureEnabled from @github-ui/feature-flags. See
     https://thehub.github.com/epd/engineering/dev-practicals/frontend/react/data-router/migration/app-payload-deprecation/ */
  const disableOrgAdminPagination = useFeatureFlag('billing_cost_centers_disable_org_admin_pagination')
  const billingCostCentersUIChanges = billingCostCentersUIPagination && !disableOrgAdminPagination
  const {path: newCostCenterUrl} = useRoute(NEW_COST_CENTER_ROUTE)
  const {path: costCentersBaseUrl} = useRoute(COST_CENTERS_ROUTE)
  const location = useLocation()
  const navigate = useNavigate()

  // Get the current state from URL parameters, defaulting to 'active'
  const stateParam = searchParams.get('state')
  const currentState =
    stateParam === CostCenterTabs.Active || stateParam === CostCenterTabs.Deleted ? stateParam : CostCenterTabs.Active

  // Get the current page from URL parameters, defaulting to 1 (only when feature flag is enabled)
  const currentPage = billingCostCentersUIChanges ? parseInt(searchParams.get('page') || '1', 10) : 1

  // Use the client-side data fetching hook for pagination with loading state
  const {
    activeCostCenters: fetchedActiveCostCenters,
    archivedCostCenters: fetchedArchivedCostCenters,
    hasNextPage: fetchedHasNextPage,
    hasUserScopedCostCenters: fetchedHasUserScopedCostCenters,
    requestState,
    isPaginationEnabled,
  } = useCostCentersPageWithLoading({
    page: currentPage,
    state: currentState,
    noop: !billingCostCentersUIChanges,
    refetchKey: reloadKey,
  })

  // Use fetched data when pagination is enabled, otherwise use initial payload
  const activeCostCenters = isPaginationEnabled ? fetchedActiveCostCenters : initialActiveCostCenters
  const archivedCostCenters = isPaginationEnabled ? fetchedArchivedCostCenters : initialArchivedCostCenters
  const hasNextPage = isPaginationEnabled ? fetchedHasNextPage : initialHasNextPage
  const hasUserScopedCostCenters = isPaginationEnabled
    ? fetchedHasUserScopedCostCenters
    : initialHasUserScopedCostCenters

  // Determine which cost centers to display based on the current state
  const displayedCostCenters = currentState === CostCenterTabs.Active ? activeCostCenters : archivedCostCenters

  // Loading state condition
  const isLoading = isPaginationEnabled && requestState === RequestState.LOADING

  const hasPreviousPage = billingCostCentersUIChanges && currentPage > 1

  // Create URLs for tab navigation, preserving the current page (only when feature flag is enabled)
  const activeTabUrl = `${costCentersBaseUrl}?state=${CostCenterTabs.Active}`
  const deletedTabUrl = `${costCentersBaseUrl}?state=${CostCenterTabs.Deleted}`

  const [isOpen, setIsOpen] = useState(false)
  const buttonRef = useRef<HTMLButtonElement>(null)
  const onDialogClose = useCallback(() => setIsOpen(false), [])

  const onDialogLinkClick = useCallback(
    (e: React.FormEvent<EventTarget>) => {
      e.preventDefault()
      return setIsOpen(!isOpen)
    },
    [isOpen],
  )

  useEffect(() => {
    if (location.state?.bannerMessage) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setResources(location.state.resources as ReassignedResource[])
      const message = location.state.bannerMessage
      setBannerMessage(message)
      setBannerType(location.state.bannerType === 'success' ? 'success' : 'critical')
      setCostCenterName(location.state.costCenterName || '')
      setShowBanner(true)

      // Announce the banner message to screen readers
      announce(message)

      // Clear the state to prevent showing the banner on future visits
      // Preserve search parameters when clearing location.state
      const fullPath = location.pathname + location.search
      navigate(fullPath, {replace: true, state: {}})
    }
  }, [location.state, navigate, location.pathname, location.search])

  // Redirect to page 1 if we're on a page > 1 with no cost centers (when server-side pagination is enabled)
  // But only redirect after loading is complete to avoid redirecting before data arrives
  useEffect(() => {
    if (billingCostCentersUIChanges && currentPage > 1 && displayedCostCenters.length === 0 && !isLoading) {
      navigate(`${costCentersBaseUrl}?state=${currentState}`, {replace: true})
    }
  }, [
    billingCostCentersUIChanges,
    currentPage,
    displayedCostCenters.length,
    navigate,
    costCentersBaseUrl,
    currentState,
    isLoading,
  ])

  const hideBanner = () => {
    setShowBanner(false)
    setBannerMessage('')
  }

  const anyCostCenters = activeCostCenters.length || archivedCostCenters.length

  // Show table interface unless we're on active tab with no cost centers at all
  // This ensures deleted tab always shows empty table instead of generic "no cost centers" page
  // Also show table interface while loading so the loading table appears immediately
  const shouldShowTableInterface = anyCostCenters || currentState === CostCenterTabs.Deleted || isLoading
  return (
    <Layout>
      <header className="Subhead">
        <Heading as="h1" className={clsx('Subhead-heading', styles.pageHeading)}>
          Cost centers
        </Heading>

        {anyCostCenters && !isStafftoolsRoute ? (
          <LinkButton href={newCostCenterUrl} variant="primary">
            New cost center
          </LinkButton>
        ) : null}
      </header>
      <CostCenterBanner />
      {orgOwnerAccessDenied && (
        <CostCenterNotification
          text="You do not have access to this cost center. Contact your administrator or billing manager."
          variant="critical"
          dismissible
          link={{
            href: 'https://docs.github.com/en/enterprise-cloud@latest/billing/tutorials/use-cost-centers',
            label: 'Learn more',
          }}
        />
      )}
      {showBanner && (
        <div style={{marginBottom: '1rem'}}>
          <Banner
            aria-label={bannerType === 'success' ? 'Success banner' : 'Error banner'}
            title={bannerType === 'success' ? 'Success' : 'Error'}
            hideTitle
            description={
              <>
                {bannerMessage}

                {resources.length > 0 && (
                  <>
                    {' '}
                    <Link href="" onClick={onDialogLinkClick} inline>
                      {`${Pluralize('resource', resources.length, true)} ${
                        resources.length === 1 ? 'has' : 'have'
                      } been moved`}
                    </Link>{' '}
                    from other cost centers.
                  </>
                )}
              </>
            }
            variant={bannerType}
            onDismiss={hideBanner}
          />
        </div>
      )}

      {isOpen && (
        <Dialog title={`Resources moved to '${costCenterName}'`} onClose={onDialogClose} returnFocusRef={buttonRef}>
          <ReassignedResources resources={resources} />
        </Dialog>
      )}

      {shouldShowTableInterface || isStafftoolsRoute ? (
        <div>
          <UnderlineNav aria-label="Cost centers selector" className={styles.costCentersSelector}>
            <UnderlineNav.Item
              as="a"
              href={activeTabUrl}
              aria-current={currentState === CostCenterTabs.Active ? 'page' : undefined}
              key={'active-cost-centers-tab'}
              data-testid={'active-cost-centers-tab'}
            >
              Active
            </UnderlineNav.Item>
            <UnderlineNav.Item
              as="a"
              href={deletedTabUrl}
              aria-current={currentState === CostCenterTabs.Deleted ? 'page' : undefined}
              key={'deleted-cost-centers-tab'}
              data-testid={'deleted-cost-centers-tab'}
            >
              Deleted
            </UnderlineNav.Item>
          </UnderlineNav>
          {isLoading ? (
            <CostCentersLoadingTable
              showDescription={billingAddCostCenterDescription}
              enterpriseTeamsEnabled={enterpriseTeamsEnabled}
            />
          ) : billingCostCentersUIChanges ? (
            <CostCentersTable
              costCenters={displayedCostCenters}
              selectedTab={currentState}
              hasUserScopedCostCenters={hasUserScopedCostCenters}
              billingAddCostCenterDescription={billingAddCostCenterDescription}
              enterpriseTeamsEnabled={enterpriseTeamsEnabled}
              currentPage={currentPage}
              hasNextPage={hasNextPage}
              hasPreviousPage={hasPreviousPage}
              totalCount={totalCount}
            />
          ) : (
            <CostCentersTable
              costCenters={displayedCostCenters}
              selectedTab={currentState}
              hasUserScopedCostCenters={hasUserScopedCostCenters}
              billingAddCostCenterDescription={billingAddCostCenterDescription}
              enterpriseTeamsEnabled={enterpriseTeamsEnabled}
            />
          )}
        </div>
      ) : (
        <div className={styles.emptyStateContainer}>
          <div className={styles.iconContainer}>
            <Octicon icon={BriefcaseIcon} size={24} />
          </div>
          <div className={styles.emptyStateContentContainer}>
            <Heading as="h1">No cost centers created</Heading>
            <p className={styles.emptyStateDescription}>
              Create cost centers to track spending and bill separately for a group of organizations and repositories
              within your enterprise.
            </p>
          </div>
          {/* eslint-disable-next-line @github-ui/dotcom-primer/no-title-case -- baselined during linter rollout */}
          <LinkButton href={newCostCenterUrl} variant="primary">
            New Cost Center
          </LinkButton>
        </div>
      )}
    </Layout>
  )
}
