import {LoadingSkeleton} from '@github-ui/skeleton/LoadingSkeleton'
import {isFeatureEnabled} from '@github-ui/feature-flags'
import {Link, ProgressBar} from '@primer/react'
import pluralize from 'pluralize'

import useRoute from '../../hooks/use-route'
import {useDiscounts} from '../../hooks/discount'
import {BUDGETS_ROUTE} from '../../routes'
import {getDaysUntilNextMonth, getMonthAndYearForPeriod} from '../../utils'
import {DISCOUNT_TARGET_DATA_MAP} from '../../utils/discount'
import {IncludedUsageDiscountTargetType, UsagePeriod, DiscountValueType} from '../../enums'
import type {IncludedUsageTileProducts} from '../../constants'
import type {DiscountStatesByDiscountMethod} from '../../types/discounts'
import type {EnabledProduct} from '../../types/products'

import styles from './IncludedUsageTile.module.css'

interface Props {
  enabledProducts: EnabledProduct[]
  selectedProduct: IncludedUsageTileProducts
  monthlyPeriod: typeof UsagePeriod.THIS_MONTH | typeof UsagePeriod.LAST_MONTH
}

interface ProgressBarData {
  key: IncludedUsageDiscountTargetType
  progress: number
  ratio: string
  title: string
  variant: string
}

// If you are changing billing platform constants consider changing here as well
// Note: this is a function and not a constant to support FF check due to SSR
function getIncludedUsageTileDiscounts(): Record<IncludedUsageTileProducts, IncludedUsageDiscountTargetType[]> {
  return {
    actions: [
      IncludedUsageDiscountTargetType.SKU_ACTIONS_MINUTES,
      IncludedUsageDiscountTargetType.SKU_ACTIONS_STORAGE,
      ...(isFeatureEnabled('actions_custom_images_storage_billing_ui_visibility')
        ? [IncludedUsageDiscountTargetType.SKU_ACTIONS_CUSTOM_IMAGE_STORAGE]
        : []),
      IncludedUsageDiscountTargetType.SKU_ACTIONS_PACKAGES_STORAGE_COMBINED,
    ],
    packages: [
      IncludedUsageDiscountTargetType.SKU_PACKAGES_BANDWIDTH,
      IncludedUsageDiscountTargetType.SKU_PACKAGES_STORAGE,
      IncludedUsageDiscountTargetType.SKU_ACTIONS_PACKAGES_STORAGE_COMBINED,
    ],
    git_lfs: [IncludedUsageDiscountTargetType.SKU_LFS_BANDWIDTH, IncludedUsageDiscountTargetType.SKU_LFS_STORAGE],
  }
}

function getProgressBarColor(percentage: number): string {
  if (percentage >= 1) return 'danger.emphasis'
  if (percentage >= 0.9) return 'attention.emphasis'
  return 'accent.emphasis'
}

function formatAppliedDiscountRatio(includedDiscountQuantity: number, unit: string, ratio: number): string {
  let appliedDiscountQuantity = ratio * includedDiscountQuantity
  appliedDiscountQuantity = Math.round(appliedDiscountQuantity * 10) / 10 // Show single decimal precision

  const includedDiscountFormatted = includedDiscountQuantity.toLocaleString()
  const appliedDiscountFormatted = appliedDiscountQuantity.toLocaleString()
  return `${appliedDiscountFormatted} ${unit} used / ${includedDiscountFormatted} ${unit} included`
}

function createProgressBarData(
  targetType: IncludedUsageDiscountTargetType,
  discountAmounts: DiscountStatesByDiscountMethod,
): ProgressBarData | null {
  const discountTargetData = DISCOUNT_TARGET_DATA_MAP[targetType]
  const fixedDiscountAmount = discountAmounts[DiscountValueType.Dollar]
  if (!discountTargetData || !fixedDiscountAmount || !fixedDiscountAmount[0]) return null

  const firstTarget = fixedDiscountAmount[0]
  const {targetAmount} = firstTarget
  const tier = discountTargetData.tiers[targetAmount]
  if (!tier) return null

  const percentage = Math.min(firstTarget.currentAmount / firstTarget.targetAmount, 1)

  return {
    key: targetType,
    progress: percentage * 100,
    ratio: formatAppliedDiscountRatio(tier.includedQuantity, discountTargetData.unit, percentage),
    title: discountTargetData.skuTitle,
    variant: getProgressBarColor(percentage),
  }
}

export default function IncludedUsageTile({enabledProducts, selectedProduct, monthlyPeriod}: Props) {
  const {path: budgetsUrl} = useRoute(BUDGETS_ROUTE)

  const {month, year} = getMonthAndYearForPeriod(monthlyPeriod)
  const {enabledProductDiscountTargetAmounts, isLoadingDiscounts} = useDiscounts({
    enabledProducts,
    filterIncludedUsage: true,
    month,
    year,
  })
  const daysUntilNextMonth = getDaysUntilNextMonth()
  const includedUsageTileDiscounts = getIncludedUsageTileDiscounts()
  const progressBarOrder = includedUsageTileDiscounts[selectedProduct]
  const progressBarsData = Object.entries(enabledProductDiscountTargetAmounts)
    .filter(([targetType]) => progressBarOrder.includes(targetType as IncludedUsageDiscountTargetType))
    .map(([targetType, discountAmounts]) =>
      createProgressBarData(targetType as IncludedUsageDiscountTargetType, discountAmounts),
    )
    .filter(data => data != null)
    .sort((a, b) => progressBarOrder.indexOf(a.key) - progressBarOrder.indexOf(b.key))

  return (
    <div className={styles.card}>
      <div className={styles.header}>
        <p className={styles.heading}>Included usage</p>
        <Link className={styles.link} inline href={budgetsUrl}>
          Manage budgets
        </Link>
      </div>
      <div className={styles.progressBarsContainer}>
        {isLoadingDiscounts ? (
          <LoadingSkeleton variant="rounded" height="84px" />
        ) : (
          progressBarsData.map(data => {
            return (
              <div className={styles.barContainer} key={data.key}>
                <div className={styles.barHeading}>
                  <span className={styles.barTitle} data-testid={`${data.key}-title`}>
                    {data.title}
                  </span>
                  <span className={styles.ratio} data-testid={`${data.key}-ratio`}>
                    {data.ratio}
                  </span>
                </div>
                <ProgressBar
                  progress={data.progress}
                  bg={data.variant}
                  aria-label={data.title}
                  data-testid={`${data.key}-progress-bar`}
                />
              </div>
            )
          })
        )}
      </div>
      {monthlyPeriod === UsagePeriod.THIS_MONTH && (
        <p className={styles.description} data-testid="included-usage-description">
          Included usage limits reset in {daysUntilNextMonth} {pluralize('day', daysUntilNextMonth)}.
        </p>
      )}
    </div>
  )
}
