import type {BudgetLimitTypes} from '../enums/budgets'

export interface Budget {
  targetType: string
  targetAmount: number
  licenseCount: number
  budgetLimitType: BudgetLimitTypes
  currentAmount: number
  currentLicenseCount: number
  targetId: string
  targetName: string
  pricingTargetId: string
  pricingTargetType: BudgetPricingTargetType
  alertEnabled: boolean
  uuid: string
  excludeCostCenterUsage?: boolean
  budgetThresholdsSummary?: BudgetThresholdsSummary
}

export type EditBudget = Budget & {
  alertEnabled: boolean
  alertRecipientUserIds: string[]
  pricingTargetId: string
  pricingTargetType: BudgetPricingTargetType
}

export type BudgetPricingTargetType = (typeof BudgetPricingTargetType)[keyof typeof BudgetPricingTargetType]

export const BudgetPricingTargetType = {
  ProductPricing: 'ProductPricing',
  SkuPricing: 'SkuPricing',
  BundlePricing: 'BundlePricing',
}

export interface BudgetAlertRecipient {
  id: string
  login: string
  name: string | null
  avatarUrl: string
}

export interface GetBudgetResponse {
  budget: EditBudget
  slug: string
}

/**
 * Response type for legacy budgets endpoint (without pagination)
 */
export interface GetBudgetsLegacyResponse {
  budgets: Budget[]
}

/**
 * Response type for paginated budgets endpoint
 */
export interface GetBudgetsPaginatedResponse {
  budgets: Budget[]
  has_next_page: boolean
  total_count?: number
  billing_budget_count_cache_enabled?: boolean
}

export interface UpsertBudgetRequest {
  targetAmount?: number
  targetType: string
  targetId: string
  pricingTargetType: string
  pricingTargetId: string
  budgetLimitType: string
  alertEnabled: boolean
  alertRecipientUserIds: string[]
  licenseCount?: number
  excludeCostCenterUsage?: boolean
}

export type BudgetVariant = 'critical' | 'warning'

export interface BudgetAlertActionDetails {
  text: string
  url_text: string
  url: string
}

export interface BudgetAlertDetails {
  text: string
  variant: BudgetVariant
  dismissible: boolean
  dismiss_link: string
  budget_id: string
}

/**
 * Map of threshold percentage to user count from the proto `budgetThresholdsSummary`.
 * Keys: 0 (0–74% usage bucket), 75, 90, 100.
 * "No usage" is derived as the remainder outside these buckets.
 */
export type BudgetThresholdsSummary = Record<number, number>

export interface MultiUserBudgetUserState {
  userId: string
  displayName?: string
  avatarUrl?: string
  currentAmount: number
  quantity: number
  targetAmount: number
  overrideBudgetId?: string
}

export interface GetMultiUserBudgetStatesResponse {
  user_states: MultiUserBudgetUserState[]
  has_next_page: boolean
  total_count: number
}

export type BudgetPicker = 'repo' | 'org' | 'enterprise' | 'cost_center'
