import {Checkbox, FormControl, Heading, Label, Link} from '@primer/react'
import {CreditCardIcon, GlobeIcon, OrganizationIcon, PersonIcon, RepoIcon} from '@primer/octicons-react'
import {useFeatureFlag} from '@github-ui/react-core/use-feature-flag'
import {clsx} from 'clsx'
import styles from './BudgetSelectedScope.module.css'

import {
  BUDGET_SCOPE_COST_CENTER,
  BUDGET_SCOPE_CUSTOMER,
  BUDGET_SCOPE_ORGANIZATION,
  BUDGET_SCOPE_REPOSITORY,
  BUDGET_SCOPE_MULTI_USER_CUSTOMER,
  BUDGET_SCOPE_USER,
  BUDGET_SCOPE_MULTI_USER_COST_CENTER,
} from '../../constants'
import {use} from 'react'
import {PageContext} from '../../App'

interface Props {
  budgetScope: string
  budgetTargetName: string
  excludeCostCenterUsage?: boolean
  setExcludeCostCenters?: (exclude: boolean) => void
  isEditMode?: boolean
}

export function BudgetSelectedScope({
  budgetScope,
  budgetTargetName,
  excludeCostCenterUsage = false,
  setExcludeCostCenters,
  isEditMode = false,
}: Props) {
  const {isOrganizationRoute, isUserRoute, isEnterpriseRoute} = use(PageContext)
  /* eslint-disable-next-line @github-ui/github-monorepo/no-use-feature-flags --
     TODO: Migrate to isFeatureEnabled from @github-ui/feature-flags. See
     https://thehub.github.com/epd/engineering/dev-practicals/frontend/react/data-router/migration/app-payload-deprecation/ */
  const isExcludeCostCentersEnabled = useFeatureFlag('billing_enterprise_budget_option_to_exclude_cost_centers')

  const getBudgetScopeDetails = (scope: string) => {
    switch (scope) {
      case BUDGET_SCOPE_CUSTOMER:
        if (isOrganizationRoute) {
          return {
            name: 'Organization',
            description: 'Scoped budgets track spending for all repositories in the organization',
          }
        } else if (isUserRoute) {
          return {
            name: 'Account',
            description: 'Scoped budgets track spending for all repositories owned by your account',
          }
        } else {
          return {
            name: 'Enterprise',
            description:
              'Scoped budgets track spending for all organizations, repositories and cost centers in the enterprise',
          }
        }
      case BUDGET_SCOPE_ORGANIZATION:
        return {
          name: 'Organization',
          description: 'Scoped budgets track spending for all repositories in the organization',
        }
      case BUDGET_SCOPE_REPOSITORY:
        return {
          name: 'Repository',
          description: 'Scoped budgets track spending for a single repository',
        }
      case BUDGET_SCOPE_COST_CENTER:
        return {
          name: 'Cost center',
          description: 'Scoped budgets track spending for a single cost center',
        }
      case BUDGET_SCOPE_MULTI_USER_CUSTOMER:
        return {
          name: 'Users',
          description: 'Each user in your enterprise gets their own individual budget',
        }
      case BUDGET_SCOPE_MULTI_USER_COST_CENTER:
        return {
          name: 'Cost center (Per-user)',
          description:
            'Applies to every licensed user in a selected cost center. Overrides the Universal budget for those users.',
        }
      case BUDGET_SCOPE_USER:
        return {
          name: 'User',
          description: 'Scoped budget for an individual user',
        }
    }
  }

  const budgetScopeDetails = getBudgetScopeDetails(budgetScope)

  const budgetScopeIconMap: {[key: string]: React.ReactElement} = {
    [BUDGET_SCOPE_CUSTOMER]: <GlobeIcon />,
    [BUDGET_SCOPE_ORGANIZATION]: <OrganizationIcon />,
    [BUDGET_SCOPE_REPOSITORY]: <RepoIcon />,
    [BUDGET_SCOPE_COST_CENTER]: <CreditCardIcon />,
    [BUDGET_SCOPE_MULTI_USER_CUSTOMER]: <PersonIcon />,
    [BUDGET_SCOPE_MULTI_USER_COST_CENTER]: <PersonIcon />,
    [BUDGET_SCOPE_USER]: <PersonIcon />,
  }

  const showExcludeCostCentersCheckbox =
    budgetScope === BUDGET_SCOPE_CUSTOMER && isEnterpriseRoute && isExcludeCostCentersEnabled

  return (
    <div className={styles.budgetSelectedScope}>
      <Heading as="h2" className={clsx('Box-title', styles.scopeHeading)}>
        Budget scope
      </Heading>
      <div className="Box">
        <div className={clsx('Box-row', styles.scopeRow)}>
          <span className={styles.scopeName}>{budgetScopeDetails?.name}</span>
          <span className={styles.scopeDescription}>{budgetScopeDetails?.description}</span>
          <div className={styles.scopeTarget}>
            {budgetScopeIconMap[budgetScope]}
            <span className={styles.scopeTargetName}>{budgetTargetName}</span>
          </div>
          {showExcludeCostCentersCheckbox && (
            <div className={styles.excludeCostCentersControl}>
              <FormControl disabled={!isEditMode}>
                <Checkbox checked={excludeCostCenterUsage} onChange={e => setExcludeCostCenters?.(e.target.checked)} />
                <FormControl.Label>
                  Exclude cost center usage from this budget <Label variant="accent">Preview</Label>
                </FormControl.Label>
                <FormControl.Caption>
                  If selected, cost center usage will <strong>not</strong> be limited by this budget.{' '}
                  <Link href="https://gh.io/exclude-cost-center" inline target="_blank" rel="noopener noreferrer">
                    Learn more.
                  </Link>
                </FormControl.Caption>
              </FormControl>
            </div>
          )}
        </div>
      </div>
    </div>
  )
}
