import {AnchoredOverlay, IconButton, Stack, Text, Link} from '@primer/react'
import {InfoIcon} from '@primer/octicons-react'
import {useState} from 'react'
import styles from './InfoIconOverlay.module.css'

interface InfoIconOverlayProps {
  infoLabel: string
  link?: string
  linkText?: string
  overlayTitle: string
  overlayText: string[]
}

export default function InfoIconOverlay({infoLabel, link, linkText, overlayTitle, overlayText}: InfoIconOverlayProps) {
  const [hintOpen, setHintOpen] = useState(false)

  return (
    <AnchoredOverlay
      align="center"
      open={hintOpen}
      onOpen={() => setHintOpen(true)}
      onClose={() => setHintOpen(false)}
      renderAnchor={props => (
        <IconButton
          aria-label={infoLabel}
          aria-labelledby={undefined}
          aria-haspopup={undefined}
          aria-expanded={undefined}
          icon={InfoIcon}
          size="small"
          variant="invisible"
          data-testid="info-icon-overlay-button"
          {...props}
        />
      )}
      side="outside-top"
      width="medium"
    >
      <Stack direction="vertical" gap="normal" justify="center" padding="normal">
        <Text size="medium" weight="semibold">
          {overlayTitle}
        </Text>
        {overlayText.map(text => (
          <Text key={text} size="medium" className={styles.OverlayText}>
            {text}
          </Text>
        ))}
        {link && linkText && (
          <Link href={link} target="_blank" rel="noopener noreferrer">
            {linkText}
          </Link>
        )}
      </Stack>
    </AnchoredOverlay>
  )
}
