import {ChevronDownIcon, ChevronRightIcon, PencilIcon, XIcon} from '@primer/octicons-react'
import {Banner, Button, FormControl, Heading, IconButton, Link, LinkButton, Radio, RadioGroup} from '@primer/react'
import {Dialog} from '@primer/react/deprecated'
import {clsx} from 'clsx'
import {useState} from 'react'

import type {Subscription} from '../../types/cost-centers'

import styles from './AzureSubscriptionDetails.module.css'

const SUPPORTED_SUBSCRIPTIONS_DOCS_URL = 'https://docs.github.com/en/billing/reference/supported-payment-methods'

interface Props {
  encodedAzureSubscriptionUri: string
  setAzureTargetId: (azureSubscriptionId: string) => void
  subscriptions: Subscription[]
  targetId: string
  // Optionally display the azure details in view-only mode
  viewOnly?: boolean
}

// A subscription is treated as billable unless the back end explicitly tells us otherwise.
function isBillable(subscription: Subscription): boolean {
  return subscription.billable !== false
}

function SubscriptionRow({subscription, billable}: {subscription: Subscription; billable: boolean}) {
  return (
    <div
      className={clsx(styles.subscriptionFormControl, !billable && styles.unsupported)}
      aria-disabled={!billable || undefined}
      data-testid={
        billable
          ? `azure-subscription-row-${subscription.subscriptionId}`
          : `azure-subscription-row-unsupported-${subscription.subscriptionId}`
      }
    >
      <FormControl disabled={!billable}>
        <Radio name="subscription" value={subscription.subscriptionId} />
        <FormControl.Label> {subscription.displayName} </FormControl.Label>
        <FormControl.Caption> {subscription.subscriptionId} </FormControl.Caption>
      </FormControl>
    </div>
  )
}

export function AzureSubscriptionDetails({
  encodedAzureSubscriptionUri,
  setAzureTargetId,
  subscriptions,
  targetId,
  viewOnly = false,
}: Props) {
  const [isOpen, setIsOpen] = useState<boolean>(true)
  const [selectedTargetId, setSelectedTargetId] = useState<string>(targetId)
  const [unsupportedExpanded, setUnsupportedExpanded] = useState<boolean>(false)

  const handleSubmit = () => {
    setAzureTargetId(selectedTargetId)
    setIsOpen(false)
  }

  const billableSubscriptions = subscriptions.filter(isBillable)
  const unsupportedSubscriptions = subscriptions.filter(s => !isBillable(s))

  if (viewOnly && !targetId) {
    return <></>
  }

  return (
    <div className={styles.cardMargin} data-testid="azure-subscription-id-box">
      <div className={styles.headingWrapper}>
        <Heading as="h3" className={clsx('h2-override-shared-component', styles.sectionHeading)}>
          Azure subscription ID
        </Heading>
        {!viewOnly && (
          <span>
            Attach an optional Azure subscription to bill usage for this cost center to a different Azure subscription
            than the enterprise default.
          </span>
        )}
      </div>
      {targetId && subscriptions ? (
        <div className={styles.subscriptionView} data-testid="azure-subscription-id-view">
          <div className={styles.subscriptionInfo}>
            <span className={styles.subscriptionName}>
              {subscriptions.find(s => s.subscriptionId === targetId)?.displayName}
            </span>
            <span className={styles.mutedText}> {targetId}</span>
          </div>
          {!viewOnly && (
            <>
              {/* eslint-disable-next-line primer-react/a11y-remove-disable-tooltip */}
              <IconButton
                unsafeDisableTooltip
                icon={PencilIcon}
                variant="invisible"
                className={styles.editButton}
                aria-label={`Change Azure subscription`}
                onClick={() => setAzureTargetId('')}
              />
              {/* eslint-disable-next-line primer-react/a11y-remove-disable-tooltip */}
              <IconButton
                unsafeDisableTooltip
                icon={XIcon}
                variant="invisible"
                className={styles.deleteButton}
                aria-label={`Delete Azure subscription`}
                onClick={() => setAzureTargetId('')}
              />
            </>
          )}
        </div>
      ) : (
        <div className={clsx('Box', styles.addSubscriptionBox)}>
          <FormControl>
            <FormControl.Label visuallyHidden>Cost center Azure Subscription ID input</FormControl.Label>
            {/* eslint-disable-next-line @github-ui/dotcom-primer/no-title-case -- baselined during linter rollout */}
            <LinkButton className={styles.addSubscriptionLink} href={encodedAzureSubscriptionUri}>
              Add Azure Subscription ID
            </LinkButton>
            {subscriptions.length > 0 && (
              <Dialog
                isOpen={isOpen}
                onDismiss={() => setIsOpen(false)}
                aria-labelledby="picker-header"
                className={styles.dialog}
              >
                <Dialog.Header id="picker-header">Connect Azure subscription</Dialog.Header>
                <div className={styles.dialogBody}>
                  {unsupportedSubscriptions.length > 0 && (
                    <Banner
                      variant="warning"
                      title="Some subscriptions are not supported"
                      className={styles.unsupportedBanner}
                      data-testid="azure-unsupported-subscriptions-banner"
                      description={
                        <>
                          One or more of your Azure subscriptions cannot be used for billing on GitHub.{' '}
                          <Link
                            href={SUPPORTED_SUBSCRIPTIONS_DOCS_URL}
                            inline
                            target="_blank"
                            rel="noopener noreferrer"
                          >
                            Learn more about supported payment methods
                          </Link>
                          .
                        </>
                      }
                    />
                  )}
                  <RadioGroup
                    name="azureSubscriptionGroup"
                    onChange={(value: string | null) => {
                      setSelectedTargetId(value ?? '')
                    }}
                  >
                    <RadioGroup.Label>
                      <Heading as="h3" className={styles.dialogSelectHeading}>
                        Select a subscription
                      </Heading>
                    </RadioGroup.Label>
                    {billableSubscriptions.map(s => (
                      <SubscriptionRow key={s.subscriptionId} subscription={s} billable />
                    ))}
                    {unsupportedSubscriptions.length > 0 && (
                      <details
                        className={styles.unsupportedSection}
                        data-testid="azure-unsupported-subscriptions-section"
                        onToggle={e => setUnsupportedExpanded((e.target as HTMLDetailsElement).open)}
                      >
                        <summary className={styles.unsupportedSummary}>
                          {unsupportedExpanded ? <ChevronDownIcon /> : <ChevronRightIcon />}
                          <span className={styles.unsupportedSummaryText}>
                            {unsupportedSubscriptions.length === 1
                              ? '1 unsupported subscription'
                              : `${unsupportedSubscriptions.length} unsupported subscriptions`}
                          </span>
                        </summary>
                        {unsupportedSubscriptions.map(s => (
                          <SubscriptionRow key={s.subscriptionId} subscription={s} billable={false} />
                        ))}
                      </details>
                    )}
                  </RadioGroup>
                </div>
                {selectedTargetId && (
                  <div className={styles.dialogFooter}>
                    <Button block variant="primary" onClick={handleSubmit}>
                      Connect
                    </Button>
                  </div>
                )}
              </Dialog>
            )}
          </FormControl>
        </div>
      )}
    </div>
  )
}
