import type React from 'react'
import {createContext, useCallback, use, useMemo, useRef, useState} from 'react'
import {Banner, Button, Link} from '@primer/react'
import {Dialog} from '@primer/react/experimental'
import {DownloadIcon, LinkExternalIcon, ArrowRightIcon} from '@primer/octicons-react'
import {isFeatureEnabled} from '@github-ui/feature-flags'
import useRoute from '../../../hooks/use-route'
import {doRequest, HTTPMethod} from '../../../hooks/use-request'
import {BUDGETS_ROUTE, USAGE_REPORT_ROUTE} from '../../../routes'
import {USAGE_REPORT_PREMIUM_REQUEST_TYPE, USAGE_REPORT_LAST_MONTH_PERIOD} from '../../../constants'
import styles from './PreviewBillDialog.module.css'

// ─── Context ────────────────────────────────────────────────────────────────────

type PreviewBillNotification = {
  id: string
  type: 'success' | 'error'
  message: string
}

type PreviewBillContextPayload = {
  addNotification: (notification: PreviewBillNotification) => void
  notifications: PreviewBillNotification[]
}

const PreviewBillContext = createContext<PreviewBillContextPayload>({
  addNotification: () => {},
  notifications: [],
})

// ─── Root ───────────────────────────────────────────────────────────────────────

function Root({children}: {children: React.ReactNode}) {
  const [notifications, setNotifications] = useState<PreviewBillNotification[]>([])

  const addNotification = useCallback((notification: PreviewBillNotification) => {
    setNotifications(prev => [...prev, notification])
  }, [])

  const ctx = useMemo(() => ({addNotification, notifications}), [addNotification, notifications])

  return <PreviewBillContext value={ctx}>{children}</PreviewBillContext>
}

// ─── Notifications ──────────────────────────────────────────────────────────────

function PreviewBillNotificationBanner({message, type, id: _id}: PreviewBillNotification) {
  const [isVisible, setIsVisible] = useState(true)

  if (!isVisible) return null

  return (
    <div aria-live="polite" aria-atomic="true">
      <Banner
        variant={type === 'error' ? 'critical' : type}
        hideTitle
        /* eslint-disable-next-line @github-ui/dotcom-primer/no-title-case -- baselined during linter rollout */
        title="Preview Bill Notification"
        onDismiss={() => setIsVisible(false)}
        className="tmp-mb-3"
      >
        <Banner.Description>{message}</Banner.Description>
      </Banner>
    </div>
  )
}

function PreviewBillNotifications() {
  const {notifications} = use(PreviewBillContext)
  const last = notifications.at(-1)
  return <>{notifications.length > 0 && last && <PreviewBillNotificationBanner key={last.id} {...last} />}</>
}

// ─── Trigger / Dialog ───────────────────────────────────────────────────────────

interface TriggerProps {
  currentUserEmail?: string
  buttonText?: string
  variant?: 'default' | 'primary'
}

function PreviewBillTrigger({currentUserEmail, buttonText, variant}: TriggerProps) {
  const [isDialogOpen, setIsDialogOpen] = useState(false)
  const returnFocusRef = useRef(null)
  const {addNotification} = use(PreviewBillContext)
  const {path: budgetsPath} = useRoute(BUDGETS_ROUTE)
  const {path: usageReportPath} = useRoute(USAGE_REPORT_ROUTE)
  const [isDownloading, setIsDownloading] = useState(false)

  const handleOpen = useCallback(() => {
    setIsDialogOpen(true)
  }, [])

  const handleClose = useCallback(() => {
    setIsDialogOpen(false)
  }, [])

  const handleDownloadCsv = useCallback(async () => {
    setIsDownloading(true)
    try {
      const {ok} = await doRequest(HTTPMethod.POST, usageReportPath, {
        period: USAGE_REPORT_LAST_MONTH_PERIOD,
        type: USAGE_REPORT_PREMIUM_REQUEST_TYPE,
      })

      if (ok) {
        addNotification({
          id: crypto.randomUUID(),
          type: 'success',
          message: currentUserEmail
            ? `We're preparing your usage report. We'll send an email to ${currentUserEmail} when it's ready.`
            : "We're preparing your usage report. We'll send an email when it's ready.",
        })
      } else {
        addNotification({
          id: crypto.randomUUID(),
          type: 'error',
          message: 'There was an issue preparing your usage report. Please try again.',
        })
      }
    } catch {
      addNotification({
        id: crypto.randomUUID(),
        type: 'error',
        message: 'There was an issue preparing your usage report. Please try again.',
      })
    } finally {
      setIsDownloading(false)
      setIsDialogOpen(false)
    }
  }, [addNotification, currentUserEmail, usageReportPath])

  return (
    <div className={styles.triggerContainer} data-testid="preview-bill-dialog-container">
      <Button ref={returnFocusRef} onClick={handleOpen} variant={variant} data-testid="preview-bill-button">
        {buttonText ?? 'Preview my bill'}
      </Button>

      {isDialogOpen && (
        <Dialog
          onClose={handleClose}
          title="Preview your AI credit usage"
          returnFocusRef={returnFocusRef}
          aria-labelledby="preview-bill-header"
          width="xlarge"
        >
          <Banner variant="info" hideTitle title="Upcoming AI credits billing change" className="tmp-mb-3">
            <Banner.Description>Insights are estimated and do not represent your actual bill.</Banner.Description>
          </Banner>

          {isFeatureEnabled('billing_usage_report_high_volume_warning') && (
            <Banner
              data-testid="high-volume-usage-report-banner"
              variant="warning"
              title="High volume of report requests"
              className="tmp-mb-3"
            >
              <Banner.Description>
                We are currently experiencing a high volume of report requests. If you make a request, you should
                receive it within an hour.
              </Banner.Description>
            </Banner>
          )}

          <p className={styles.introText}>
            Starting June 1, 2026, Copilot usage will be measured and billed in AI credits instead of premium request
            units. Preview how your past usage maps to AI credits using the tools below.
          </p>
          <div className={styles.prepareSection}>
            <p className={styles.prepareSectionHeading}>Prepare for the upcoming change</p>

            <Link
              href="https://gh.io/ghcp-billing-preview-docs"
              target="_blank"
              rel="noopener noreferrer"
              className={styles.prepareCard}
              data-testid="preview-bill-docs-link"
            >
              <span className={styles.prepareCardTitle}>
                Refer to documentation <ArrowRightIcon size={16} />
              </span>
              <span className={styles.prepareCardDescription}>
                Explore and learn how AI credits work and how to optimize your usage.
              </span>
            </Link>

            <Link href={budgetsPath} className={styles.prepareCard} data-testid="preview-bill-set-budget-link">
              <span className={styles.prepareCardTitle}>
                Set a budget <ArrowRightIcon size={16} />
              </span>
              <span className={styles.prepareCardDescription}>
                Your existing Premium request budgets will be migrated to AI credits. Review and adjust as needed to
                prepare.
              </span>
            </Link>
          </div>

          <p className={styles.supportText}>
            Have questions?{' '}
            <Link
              href="https://support.github.com"
              target="_blank"
              rel="noopener noreferrer"
              inline
              data-testid="preview-bill-support-link"
            >
              Reach out to us
            </Link>{' '}
            for help with your transition.
          </p>

          <div className={styles.dialogFooter}>
            <div className={styles.footerActionGroup}>
              <p className={styles.footerActionHelper}>
                Download the CSV report of your premium request usage, which now includes new columns converting past
                data to AI credits.
              </p>
              <Button
                className={styles.footerAction}
                variant="primary"
                leadingVisual={<DownloadIcon />}
                onClick={handleDownloadCsv}
                disabled={isDownloading}
                data-testid="preview-bill-download-csv"
              >
                {isDownloading ? 'Preparing report…' : 'Download CSV'}
              </Button>
            </div>
            <div className={styles.footerActionGroup}>
              <p className={styles.footerActionHelper}>Use the preview app to explore the CSV interactively.</p>
              <Button
                className={styles.footerAction}
                as="a"
                href="https://copilot-billing-preview.github.com/"
                target="_blank"
                rel="noopener noreferrer"
                leadingVisual={<LinkExternalIcon />}
                data-testid="preview-bill-full-preview-link"
              >
                Explore usage and trends
              </Button>
            </div>
          </div>
        </Dialog>
      )}
    </div>
  )
}

// ─── Export ──────────────────────────────────────────────────────────────────────

export default Object.assign(Root, {
  Trigger: PreviewBillTrigger,
  Notifications: PreviewBillNotifications,
})
