import {OrganizationIcon, TriangleDownIcon} from '@primer/octicons-react'
import {Button} from '@primer/react'
import {useMemo, useState, useCallback} from 'react'

import useCostCentersPageWithLoading from '../../hooks/cost_centers/use-cost-centers-page-with-loading'
import {RequestState} from '../../enums'

import styles from './PaginatedCostCenterPicker.module.css'

import {SelectedRows} from './SelectedRows'
import {PaginatedPickerDialog} from './PaginatedPickerDialog'

import type {Item} from '../../types/common'
import type {CostCenter} from '../../types/cost-centers'

const PICKER_PAGE_SIZE = 10

interface Props {
  setAllSelectedCostCenters: (selectedIds: string[]) => void
  selectionVariant?: 'multiple' | 'single'
}

export function PaginatedCostCenterPicker({setAllSelectedCostCenters, selectionVariant}: Props) {
  const [open, setOpen] = useState<boolean>(false)
  const [currentPage, setCurrentPage] = useState<number>(1)
  const [searchQuery, setSearchQuery] = useState<string>('')
  const [refetchKey, setRefetchKey] = useState<number>(0)

  const {activeCostCenters, requestState, totalCount} = useCostCentersPageWithLoading({
    page: currentPage,
    pageSize: PICKER_PAGE_SIZE,
    state: 'active',
    query: searchQuery,
    refetchKey,
    forcePagination: true,
    preserveStaleData: true,
  })

  const isLoading = requestState === RequestState.LOADING

  const items = useMemo(() => {
    const mapped = activeCostCenters.map(
      (item: CostCenter): Item<string> => ({
        id: item.costCenterKey.uuid,
        text: item.name,
        leadingVisual: () => <OrganizationIcon />,
        rowLeadingVisual: () => <OrganizationIcon />,
        viewOnly: false,
      }),
    )
    return mapped
  }, [activeCostCenters])

  // Confirmed selection - only updated on submit, shown in SelectedRows
  const [confirmedSelection, setConfirmedSelection] = useState<Array<Item<string>>>([])

  // Pending selection - tracks selection during dialog session, persists across page changes
  const [pendingSelection, setPendingSelection] = useState<Array<Item<string>>>([])

  const pageCount = Math.ceil(totalCount / PICKER_PAGE_SIZE)

  const filterItems = useCallback(
    (value: string) => {
      const normalized = value.trim().toLowerCase()
      setSearchQuery(normalized)
      setCurrentPage(1) // Reset to first page on search
      setRefetchKey(prev => prev + 1)
    },
    [setSearchQuery, setCurrentPage, setRefetchKey],
  )

  const onPageChange = useCallback((event: React.MouseEvent, page: number) => {
    event.preventDefault()
    setCurrentPage(page)
    setRefetchKey(prev => prev + 1)
  }, [])

  const canRemoveOption = confirmedSelection.length > 0
  const removeOption = (id: string) => {
    if (!canRemoveOption) return

    const newOptions = confirmedSelection.filter(option => option.id !== id)
    setConfirmedSelection(newOptions)
    setAllSelectedCostCenters(newOptions.map(opt => opt.id))
  }

  const onDialogSubmit = (newSelected: Array<Item<string>>) => {
    setOpen(false)
    setConfirmedSelection(newSelected)
    setAllSelectedCostCenters(newSelected.map(opt => opt.id))
    // Reset search and page so reopening shows the full unfiltered list
    setSearchQuery('')
    setCurrentPage(1)
  }

  // Update pending selection immediately when user selects, so it persists across page changes
  // (ItemPicker remounts when loading state changes during pagination)
  const onSelectionChange = useCallback((newSelected: Array<Item<string>>) => {
    setPendingSelection(newSelected)
  }, [])

  const openDialog = useCallback(() => {
    // Initialize pending selection from confirmed when opening
    setPendingSelection(confirmedSelection)
    setOpen(true)
  }, [confirmedSelection])

  const resetDialog = () => {
    setOpen(false)
    // Discard pending selection, reset search and page
    setPendingSelection([])
    setSearchQuery('')
    setCurrentPage(1)
  }

  return (
    <div className={styles.wrapper}>
      <Button onClick={openDialog} className={styles.selectButton} trailingAction={TriangleDownIcon}>
        Select cost center
      </Button>
      <PaginatedPickerDialog
        open={open}
        resetDialog={resetDialog}
        filter={filterItems}
        selectAll={false}
        selected={pendingSelection}
        onDialogSubmit={onDialogSubmit}
        items={items}
        totalItemsCount={totalCount}
        pickerType="cost center"
        loading={isLoading}
        selectionVariant={selectionVariant}
        pageCount={pageCount}
        currentPage={currentPage}
        onPageChange={onPageChange}
        showPaginatedItems={pageCount > 1}
        onSelectionChange={onSelectionChange}
      />
      <SelectedRows selected={confirmedSelection} removeOption={removeOption} />
    </div>
  )
}
