import type {CostCenterUsageLineItem, ProductUsageLineItem, RepoUsageLineItem, UsageLineItem} from '../types/usage'

export const isProductUsageLineItem = (lineItem: UsageLineItem): lineItem is ProductUsageLineItem => {
  return (lineItem as ProductUsageLineItem).sku !== undefined
}

export const isRepoUsageLineItem = (lineItem: UsageLineItem): lineItem is RepoUsageLineItem => {
  return (lineItem as RepoUsageLineItem).org !== undefined
}

// Cost center line items are identified by usageType "topcostcenter" set by the backend
// This distinguishes NEW cost center format (from get_top_cost_center_line_items API)
// from OLD format which used ProductUsageLineItem with sku property
export const isCostCenterUsageLineItem = (lineItem: UsageLineItem): lineItem is CostCenterUsageLineItem => {
  return lineItem.usageType === 'topcostcenter'
}
