import {use} from 'react'
import {PageContext} from '../../App'

import {SummaryUsageCard, CurrentDiscountsListDialog} from '.'
import {getCurrentMonthDateRange} from '../../utils'

import type {DiscountStatesByTargetType, DiscountState} from '../../types/discounts'

interface DiscountUsageCardProps {
  isEnterpriseOrgOwner: boolean
  isCopilotPremiumUsageReportEnabled: boolean
  isLoadingDiscounts: boolean
  totalDiscount: number
  discountTargetAmounts: DiscountStatesByTargetType
  discountStates: DiscountState[]
  isTokenBasedBillingEnabled?: boolean
}

export default function DiscountUsageCard({
  isEnterpriseOrgOwner,
  isCopilotPremiumUsageReportEnabled,
  isLoadingDiscounts,
  totalDiscount,
  discountTargetAmounts,
  discountStates,
  isTokenBasedBillingEnabled = false,
}: DiscountUsageCardProps) {
  const isOrganization = use(PageContext).isOrganizationRoute
  const isUser = use(PageContext).isUserRoute

  const headerAction = !isEnterpriseOrgOwner ? (
    <CurrentDiscountsListDialog
      discountStatesMap={discountTargetAmounts}
      discountStates={discountStates}
      totalDiscount={totalDiscount}
      isOrganization={isOrganization}
      isUser={isUser}
      isEnterpriseOrgOwner={isEnterpriseOrgOwner}
      isCopilotPremiumUsageReportEnabled={isCopilotPremiumUsageReportEnabled}
      isTokenBasedBillingEnabled={isTokenBasedBillingEnabled}
    />
  ) : undefined

  return (
    <SummaryUsageCard
      headerAction={headerAction}
      heading="Current included usage"
      description={`Included usage discounts for ${getCurrentMonthDateRange()}.`}
      monetaryValue={totalDiscount}
      testId="total-discount"
      isLoading={isLoadingDiscounts}
    />
  )
}
