import {Heading} from '@primer/react'
import {clsx} from 'clsx'
import {use, useEffect, useState} from 'react'

import type {Product} from '../../types/products'
import type {PricingDetails} from '../../types/pricings'
import styles from './BudgetSelectedProduct.module.css'
import {BudgetCopilotPolicyLink} from './BudgetCopilotPolicyLink'
import {PageContext} from '../../App'

interface Props {
  budgetValue: string
  enabledProducts: Product[]
  enabledSkus: PricingDetails[]
  isTokenBasedBillingEnabled?: boolean
}

export function BudgetSelectedProduct({
  budgetValue,
  enabledProducts,
  enabledSkus,
  isTokenBasedBillingEnabled = false,
}: Props) {
  const [budgetValueName, setBudgetValueName] = useState<string>('')
  const [budgetHeaderName, setBudgetHeaderName] = useState<string>('')
  const {isOrganizationRoute, isUserRoute} = use(PageContext)

  useEffect(() => {
    const product = enabledProducts.find(item => item.name === budgetValue)
    if (product) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setBudgetValueName(product.friendlyProductName)
      setBudgetHeaderName('Product')
      return
    }

    const sku = enabledSkus.find(item => item.sku === budgetValue)
    if (sku) {
      setBudgetValueName(sku.friendlyName)
      setBudgetHeaderName('SKU')
    }

    if (budgetValue === 'premium_requests') {
      setBudgetHeaderName('SKU')
      setBudgetValueName(isTokenBasedBillingEnabled ? 'All AI Credit SKUs' : 'All Premium Request SKUs')
    }
  }, [budgetValue, enabledProducts, enabledSkus, isTokenBasedBillingEnabled])

  return (
    <div className={styles.budgetSelectedProduct}>
      <Heading as="h2" className={clsx(styles.sectionHeading, 'Box-title')}>
        {budgetHeaderName ?? 'Unknown'}
      </Heading>
      <div className="Box">
        <div className="Box-row">
          <span className={styles.boldText}>{budgetValueName ?? 'Unknown'}</span>
          {budgetValue === 'premium_requests' && (
            <>
              <p className={styles.BundleBudgetText}>
                A budget for all SKUs that consume {isTokenBasedBillingEnabled ? 'AI credits' : 'premium requests'}
                {!isUserRoute ? (
                  <>
                    , where{' '}
                    <BudgetCopilotPolicyLink
                      isOrganizationRoute={isOrganizationRoute}
                      isTokenBasedBillingEnabled={isTokenBasedBillingEnabled}
                    />
                  </>
                ) : (
                  '.'
                )}
              </p>
              {/* eslint-disable-next-line @github-ui/dotcom-primer/no-title-case -- baselined during linter rollout */}
              <span className={styles.BundleBudgetSubtext}>Supported SKUs:</span>
              <ul className={styles.BundleBudgetList}>
                <li>{isTokenBasedBillingEnabled ? 'Copilot AI credits' : 'Copilot premium requests'}</li>
                <li>{isTokenBasedBillingEnabled ? `Cloud Agent AI credits` : `Cloud Agent premium requests`}</li>
                <li>{isTokenBasedBillingEnabled ? 'Spark AI credits' : 'Spark premium requests'}</li>
              </ul>
            </>
          )}
        </div>
      </div>
    </div>
  )
}
