import {LoadingSkeleton} from '@github-ui/skeleton/LoadingSkeleton'
import {AlertIcon} from '@primer/octicons-react'
import {ProgressBar} from '@primer/react'

import styles from './AIUsageSummaryCard.module.css'
import {RequestState} from '../../../enums'
import {parseFormattedNumber} from '../../../utils/usage'

import type {ReactNode} from 'react'

export function getProgressBarColor(usageValue: number, entitlementValue: number, progressPercentage: number): string {
  if (usageValue > entitlementValue) return 'danger.emphasis'
  if (progressPercentage >= 90) return 'attention.emphasis'
  return 'accent.emphasis'
}

export function getCfiProgressBarColor(percentUsed: number): string {
  if (percentUsed >= 100) return 'danger.emphasis'
  if (percentUsed > 75) return 'attention.emphasis'
  return 'success.emphasis'
}

function getThresholdAriaStatus(usageValue: number, entitlementValue: number, progressPercentage: number): string {
  if (usageValue > entitlementValue) return ', limit exceeded'
  if (entitlementValue > 0 && usageValue === entitlementValue) return ', limit reached'
  if (progressPercentage >= 90) return ', nearing limit'
  return ''
}

interface AIUsageSummaryCardProps {
  title: ReactNode
  value: string | number
  description: string | ReactNode
  testId?: string
  requestState: RequestState
  showProgressBar?: boolean
  entitlementValue?: number
  variant?: 'premium-requests' | 'ai-usage'
  hideEntitlementText?: boolean
  progressValue?: number
  customEntitlementText?: string
  progressAriaLabel?: string
  progressAriaValueText?: string
  progressBarColor?: string
}

export default function AIUsageSummaryCard({
  title,
  value,
  description,
  testId,
  requestState,
  showProgressBar,
  entitlementValue,
  variant = 'premium-requests',
  hideEntitlementText = false,
  progressValue,
  customEntitlementText,
  progressAriaLabel,
  progressAriaValueText,
  progressBarColor,
}: AIUsageSummaryCardProps) {
  const formattedValue = typeof value === 'number' ? value.toLocaleString() : value
  const formattedEntitlementValue = entitlementValue?.toLocaleString() || '0'
  const numericValue = progressValue ?? (typeof value === 'string' ? parseFormattedNumber(value) : value)
  const progressPercentage = entitlementValue ? Math.min(((numericValue ?? 0) / entitlementValue) * 100, 100) : 0
  const usageUnit = variant === 'ai-usage' ? 'AI credits' : 'premium requests'
  const thresholdAriaStatus = getThresholdAriaStatus(numericValue ?? 0, entitlementValue ?? 0, progressPercentage)

  const ariaValueText = `${formattedValue} of ${formattedEntitlementValue} ${usageUnit} used${thresholdAriaStatus}`

  const entitlementText =
    customEntitlementText ??
    (variant === 'ai-usage' ? `/ ${formattedEntitlementValue} AI credits` : `of ${formattedEntitlementValue} included`)

  return (
    <div className={styles.summaryCard} data-testid={testId}>
      <p className={styles.cardTitle}>{title}</p>
      {requestState === RequestState.IDLE ? (
        <div className={styles.cardValueTextContainer}>
          <p className={styles.cardValue}>{formattedValue}</p>
          {showProgressBar && !hideEntitlementText && <p className={styles.entitlementText}>{entitlementText}</p>}
        </div>
      ) : requestState === RequestState.ERROR ? (
        <div className={styles.cardValueError}>
          <AlertIcon className="fgColor-danger" /> Something went wrong
        </div>
      ) : (
        <div className={styles.cardValue}>
          <LoadingSkeleton variant="rounded" width="100%" height="1.80rem" />
        </div>
      )}
      {showProgressBar && requestState === RequestState.IDLE && (
        <ProgressBar
          className={styles.progressBar}
          aria-label={progressAriaLabel ?? `Included ${usageUnit} progress`}
          aria-valuetext={progressAriaValueText ?? ariaValueText}
          bg={progressBarColor ?? getProgressBarColor(numericValue ?? 0, entitlementValue ?? 0, progressPercentage)}
          progress={progressPercentage}
          barSize="small"
        />
      )}
      <p className={styles.cardDescription}>{description}</p>
    </div>
  )
}
