import {ActionList, ActionMenu, IconButton, Label, Spinner, VisuallyHidden} from '@primer/react'
import {Table, DataTable, Blankslate} from '@primer/react/experimental'
import type {Column} from '@primer/react/experimental'
import {KebabHorizontalIcon, PeopleIcon, AlertIcon, PencilIcon, GraphIcon, InfoIcon} from '@primer/octicons-react'
import {GitHubAvatar} from '@github-ui/github-avatar'
import {useNavigate} from '@github-ui/use-navigate'

import ServerSidePagination from '../common/ServerSidePagination'
import {formatMoneyDisplay} from '../../utils/money'
import {RequestState} from '../../enums'
import {BUDGETS_PAGE_SIZE} from '../../constants'
import {Bundles} from '../../constants/products'
import type {Budget, MultiUserBudgetUserState} from '../../types/budgets'

import styles from './MultiUserBudgetStatesTable.module.css'

interface Props {
  userStates: MultiUserBudgetUserState[]
  requestState: RequestState
  currentPage: number
  onPageChange: (page: number) => void
  hasNextPage: boolean
  totalCount: number
  pageSize?: number
  newBudgetPath?: string
  editBudgetPathFor?: (budgetUUID: string) => string
  analyticsPath?: string
  customerId?: string
  budget?: Budget
  sortOrder?: 'ascending' | 'descending'
  onSortChange?: (direction: 'ascending' | 'descending') => void
  canManageBudgets?: boolean
}

interface UserRow {
  id: string
  userId: string
  displayName?: string
  avatarUrl?: string
  targetAmount: number
  currentAmount: number
  hasOverride: boolean
  overrideBudgetId?: string
}

export default function MultiUserBudgetStatesTable({
  customerId,
  budget,
  userStates,
  requestState,
  currentPage,
  onPageChange,
  hasNextPage,
  totalCount,
  pageSize = BUDGETS_PAGE_SIZE,
  newBudgetPath,
  editBudgetPathFor,
  analyticsPath,
  sortOrder = 'descending',
  onSortChange,
  canManageBudgets = false,
}: Props) {
  if (requestState === RequestState.LOADING || requestState === RequestState.INIT) {
    return (
      <div className={styles.loadingContainer}>
        <Spinner size="large" />
      </div>
    )
  }

  if (requestState === RequestState.ERROR) {
    return (
      <Blankslate border>
        <Blankslate.Visual>
          <PeopleIcon size={24} />
        </Blankslate.Visual>
        <Blankslate.Heading>Unable to load user budgets</Blankslate.Heading>
        <Blankslate.Description>
          An error occurred while loading user budget data. Please try again.
        </Blankslate.Description>
      </Blankslate>
    )
  }

  if (userStates.length === 0) {
    return (
      <Blankslate border>
        <Blankslate.Visual>
          <InfoIcon size={24} />
        </Blankslate.Visual>
        <Blankslate.Heading>No usage data displayed</Blankslate.Heading>
        <Blankslate.Description>
          Users will appear here once they start using AI credits this month. Usage before budget creation isn&apos;t
          counted in the current billing cycle.
        </Blankslate.Description>
        <Blankslate.SecondaryAction href="https://docs.github.com/en/billing/concepts/budgets-and-alerts#types-and-scopes">
          Learn more about user budget types
        </Blankslate.SecondaryAction>
      </Blankslate>
    )
  }

  const rows: UserRow[] = userStates.map(userState => ({
    id: userState.userId,
    userId: userState.userId,
    displayName: userState.displayName,
    avatarUrl: userState.avatarUrl,
    targetAmount: userState.targetAmount,
    currentAmount: userState.currentAmount,
    hasOverride: !!userState.overrideBudgetId,
    overrideBudgetId: userState.overrideBudgetId,
  }))

  const handleSortToggle = () => {
    onSortChange?.(sortOrder === 'descending' ? 'ascending' : 'descending')
  }

  const startItem = (currentPage - 1) * pageSize + 1
  const endItem = Math.min(currentPage * pageSize, totalCount || rows.length)

  const columns: Array<Column<UserRow>> = [
    {
      id: 'user',
      header: 'User',
      field: 'userId',
      rowHeader: true,
      width: 'grow',
      renderCell: (row: UserRow) => (
        <span className={styles.userCell}>
          {row.avatarUrl ? (
            <GitHubAvatar src={row.avatarUrl} size={20} />
          ) : (
            <span className={styles.avatarPlaceholder} />
          )}
          <span className={styles.userName}>{row.displayName || row.userId}</span>
        </span>
      ),
    },
    {
      id: 'budget',
      header: 'Budget',
      field: 'targetAmount',
      width: 'auto',
      align: 'end',
      minWidth: '200px',
      renderCell: (row: UserRow) => (
        <span className={styles.budgetCellWrapper}>
          <span className={styles.overrideCell}>
            {row.hasOverride && (
              <Label variant="accent" className={styles.overrideLabel}>
                Override
              </Label>
            )}
          </span>
          <span className={styles.targetAmount}>{formatMoneyDisplay(row.targetAmount, 0)}</span>
        </span>
      ),
    },
    {
      id: 'used',
      header: () => (
        <button
          type="button"
          onClick={handleSortToggle}
          className={styles.sortableHeader}
          aria-label={`Sort by used amount ${sortOrder === 'descending' ? 'ascending' : 'descending'}`}
          data-testid="sort-used-button"
        >
          <span className={styles.sortIcon}>{sortOrder === 'descending' ? '↓' : '↑'}</span> Used
        </button>
      ),
      field: 'currentAmount',
      width: 'auto',
      align: 'end',
      minWidth: '100px',
      renderCell: (row: UserRow) => {
        const isAtOrOverLimit = row.targetAmount > 0 && row.currentAmount >= row.targetAmount
        return (
          <span className={styles.usedCell}>
            {isAtOrOverLimit && (
              <AlertIcon size={16} className={styles.alertIconDanger} data-testid="usage-alert-icon" />
            )}
            {formatMoneyDisplay(row.currentAmount)}
          </span>
        )
      },
    },
    {
      id: 'actions',
      header: () => <VisuallyHidden>Actions</VisuallyHidden>,
      field: 'id',
      width: 'auto',
      align: 'end',
      renderCell: (row: UserRow) => (
        <UserActions
          userId={row.userId}
          displayName={row.displayName}
          targetAmount={row.targetAmount}
          overrideBudgetId={row.overrideBudgetId}
          analyticsPath={analyticsPath}
          canManageBudgets={canManageBudgets}
          editBudgetPathFor={editBudgetPathFor}
          newBudgetPath={newBudgetPath}
          customerId={customerId}
          budget={budget}
        />
      ),
    },
  ]

  return (
    <div>
      <Table.Container>
        <DataTable aria-label="User budget states" data={rows} columns={columns} />
      </Table.Container>

      {totalCount > 0 && (
        <p className={styles.pageCount} data-testid="page-count">
          {startItem}&ndash;{endItem} of {totalCount}
        </p>
      )}

      <ServerSidePagination
        currentPage={currentPage}
        onPageChange={onPageChange}
        hasNextPage={hasNextPage}
        hasPreviousPage={currentPage > 1}
        totalCount={totalCount}
        pageSize={pageSize}
      />
    </div>
  )
}

interface UserActionsProps {
  userId: string
  displayName?: string
  targetAmount: number
  overrideBudgetId?: string
  analyticsPath?: string
  canManageBudgets?: boolean
  editBudgetPathFor?: (budgetUUID: string) => string
  newBudgetPath?: string
  customerId?: string
  budget?: Budget
}

function UserActions({
  userId,
  customerId,
  displayName,
  targetAmount,
  overrideBudgetId,
  analyticsPath,
  canManageBudgets,
  editBudgetPathFor,
  newBudgetPath,
  budget,
}: UserActionsProps) {
  const navigate = useNavigate()

  const handleViewUsageAnalytics = () => {
    if (analyticsPath) {
      const userArg = encodeURIComponent(`user:${displayName || userId}`)
      window.location.href = `${analyticsPath}?period=3&group=7&customer=${customerId}&query=${userArg}`
    }
  }

  const handleEditBudget = () => {
    if (!budget) return
    const baseParams = {
      hasMultiUserBudget: 'true',
      multiUserBudgetUUID: budget.uuid,
    }
    if (overrideBudgetId && editBudgetPathFor) {
      const params = new URLSearchParams(baseParams)
      navigate(`${editBudgetPathFor(overrideBudgetId)}?${params.toString()}`)
    } else if (newBudgetPath) {
      const params = new URLSearchParams({
        ...baseParams,
        product: Bundles.PremiumRequests,
        scope: 'User',
        user: displayName || userId,
        amount: String(targetAmount),
      })
      navigate(`${newBudgetPath}?${params.toString()}`)
    }
  }

  return (
    <ActionMenu>
      <ActionMenu.Anchor>
        {/* eslint-disable-next-line primer-react/a11y-remove-disable-tooltip */}
        <IconButton
          unsafeDisableTooltip
          icon={KebabHorizontalIcon}
          variant="invisible"
          aria-label={`Actions for ${displayName || userId}`}
          size="small"
          data-testid={`user-actions-${userId}`}
        />
      </ActionMenu.Anchor>
      <ActionMenu.Overlay>
        <ActionList>
          {canManageBudgets && (
            <ActionList.Item onSelect={handleEditBudget} data-testid={`edit-budget-${userId}`}>
              <ActionList.LeadingVisual>
                <PencilIcon />
              </ActionList.LeadingVisual>
              Edit budget
            </ActionList.Item>
          )}
          <ActionList.Item onSelect={handleViewUsageAnalytics} data-testid={`view-analytics-${userId}`}>
            <ActionList.LeadingVisual>
              <GraphIcon />
            </ActionList.LeadingVisual>
            View usage analytics
          </ActionList.Item>
        </ActionList>
      </ActionMenu.Overlay>
    </ActionMenu>
  )
}
