/* eslint relay/unused-fields: off */
import {PeopleIcon, TriangleDownIcon} from '@primer/octicons-react'
import {clsx} from 'clsx'
import Pluralize from 'pluralize'
import {useCallback} from 'react'

import {graphql, usePaginationFragment, usePreloadedQuery, type PreloadedQuery} from 'react-relay'

import {SelectedRows} from './SelectedRows'
import {PickerDialog} from './PickerDialog'
import {PickerHeader} from './PickerHeader'
import type {PaginatedEnterpriseTeamPickerFragment$data} from './__generated__/PaginatedEnterpriseTeamPickerFragment.graphql'
import type {
  PaginatedEnterpriseTeamPickerTeams$data,
  PaginatedEnterpriseTeamPickerTeams$key,
} from './__generated__/PaginatedEnterpriseTeamPickerTeams.graphql'
import type {PaginatedEnterpriseTeamListQuery} from './__generated__/PaginatedEnterpriseTeamListQuery.graphql'
import type {PaginatedEnterpriseTeamPickerGraphqlQuery} from './__generated__/PaginatedEnterpriseTeamPickerGraphqlQuery.graphql'
import {Banner, Button, FormControl} from '@primer/react'
import styles from './PaginatedEnterpriseTeamPicker.module.css'
import {PAGE_SIZE, PaginatedPicker, SELECTED_ITEMS_PAGE_SIZE} from './PaginatedPicker'
import ResourcePaginator from './ResourcePaginator'

export type EnterpriseTeam = PaginatedEnterpriseTeamPickerFragment$data

// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-queries
export const PaginatedEnterpriseTeamPickerFragment = graphql`
  fragment PaginatedEnterpriseTeamPickerFragment on EnterpriseTeam @inline {
    id
    name
    slug
  }
`

// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-queries
export const EnterpriseTeamPickerParentGraphqlQuery = graphql`
  query PaginatedEnterpriseTeamPickerGraphqlQuery($slug: String!, $query: String) {
    enterprise(slug: $slug) {
      ...PaginatedEnterpriseTeamPickerTeams @arguments(query: $query)
    }
  }
`

// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-queries
export const PaginatedEnterpriseTeamPickerFetchedByIDQuery = graphql`
  query PaginatedEnterpriseTeamPickerFetchedByIDQuery($ids: [ID!]!) {
    nodes(ids: $ids) {
      # eslint-disable-next-line relay/must-colocate-fragment-spreads
      ...PaginatedEnterpriseTeamPickerFragment @dangerously_unaliased_fixme
      __typename
    }
  }
`

// BATCH_SIZE=100. @argumentDefinitions must be literals
const PaginatedEnterpriseTeamsGraphqlQuery = (enterpriseTeamsRef: PaginatedEnterpriseTeamPickerTeams$key) => {
  const {data, loadNext, isLoadingNext, hasNext, refetch} = usePaginationFragment<
    PaginatedEnterpriseTeamListQuery,
    PaginatedEnterpriseTeamPickerTeams$key
  >(
    // eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-queries
    graphql`
      fragment PaginatedEnterpriseTeamPickerTeams on Enterprise
      @argumentDefinitions(first: {type: "Int", defaultValue: 100}, after: {type: "String"}, query: {type: "String"})
      @refetchable(queryName: "PaginatedEnterpriseTeamListQuery") {
        enterpriseTeams(first: $first, after: $after, query: $query, orderBy: {field: NAME, direction: ASC})
          @connection(key: "PaginatedEnterpriseTeamListFragment_enterpriseTeams") {
          edges {
            node {
              # eslint-disable-next-line relay/must-colocate-fragment-spreads
              ...PaginatedEnterpriseTeamPickerFragment
            }
          }
          totalCount
        }
      }
    `,
    enterpriseTeamsRef,
  )
  return {data, loadNext, isLoadingNext, hasNext, refetch}
}

interface Props {
  initialSelectedItemIds: string[]
  preloadedEnterpriseTeamsRef: PreloadedQuery<PaginatedEnterpriseTeamPickerGraphqlQuery>
  setSelectedItems: (selectedIds: string[]) => void
  entityType?: 'budget' | 'cost center'
  indent?: boolean
  selectionVariant?: 'multiple' | 'single'
  valid?: boolean
  // Optionally display the picker in view-only mode
  viewOnly?: boolean
}

export function PaginatedEnterpriseTeamPicker({
  initialSelectedItemIds,
  preloadedEnterpriseTeamsRef,
  setSelectedItems,
  entityType = 'budget',
  indent = true,
  selectionVariant,
  valid,
  viewOnly = false,
}: Props) {
  const convertToItemProps = useCallback(
    (item: EnterpriseTeam) => {
      return {
        id: item.id,
        text: item.name,
        leadingVisual: () => <PeopleIcon />,
        rowLeadingVisual: () => <PeopleIcon />,
        viewOnly,
      }
    },
    [viewOnly],
  )

  const preloadedData = usePreloadedQuery(EnterpriseTeamPickerParentGraphqlQuery, preloadedEnterpriseTeamsRef)
  const dataRef = preloadedData.enterprise

  const {
    localSelected,
    selectedCount,
    selectAll,
    open,
    pageCount,
    currentPage,
    error,
    items,
    onPageChange,
    filterItems,
    onDialogSubmit,
    resetDialog,
    openDialog,
    removeOption,
    totalItemCount,
    itemsLoading,
    onSelectedItemsPageChange,
    selectedItemsPageCount,
    selectedItemsCurrentPage,
    pagedSelectedItems,
  } = PaginatedPicker<EnterpriseTeam, PaginatedEnterpriseTeamPickerTeams$key, PaginatedEnterpriseTeamPickerTeams$data>({
    initialSelectedItemIds,
    dataRef,
    convertToItemProps,
    setSelectedItems,
    paginatedQuery: ref => {
      const {data, loadNext, isLoadingNext, hasNext, refetch} = PaginatedEnterpriseTeamsGraphqlQuery(ref)
      return {
        data,
        loadNext: (count: number) => loadNext(count),
        isLoadingNext,
        hasNext,
        refetch,
      }
    },
    selectedItemsFetchQuery: PaginatedEnterpriseTeamPickerFetchedByIDQuery,
    searchParamName: 'query',
  })

  const pickerText = selectionVariant === 'multiple' ? 'enterprise teams' : 'enterprise team'
  return (
    <>
      {/* eslint-disable-next-line @github-ui/dotcom-primer/no-title-case -- baselined during linter rollout */}
      <PickerHeader title="Enterprise Teams" />
      <div className={clsx(styles.wrapper, indent && styles.indent)}>
        {error && <Banner variant="critical" title={error} />}
        {!viewOnly && (
          <>
            <Button
              data-testid="open-enterprise-team-picker-dialog-button"
              onClick={openDialog}
              className={styles.selectButton}
              trailingAction={TriangleDownIcon}
            >
              Select {pickerText}
            </Button>
            <PickerDialog
              open={open}
              resetDialog={resetDialog}
              filter={filterItems}
              selectAll={selectAll}
              selected={localSelected}
              onDialogSubmit={onDialogSubmit}
              items={items || []}
              totalItemsCount={totalItemCount}
              pickerType={pickerText}
              loading={false}
              selectionVariant={selectionVariant}
              entityType={entityType}
              pageSize={PAGE_SIZE}
              pageCount={pageCount}
              currentPage={currentPage}
              onPageChange={onPageChange}
              showPaginatedItems
            />
            {valid === false && (
              <FormControl.Validation variant="error" style={{marginTop: '4px'}}>
                Please select at least one enterprise team
              </FormControl.Validation>
            )}
          </>
        )}
        {selectAll && (
          <span className={styles.smallText}>All {Pluralize('enterprise team', totalItemCount, true)} selected</span>
        )}
        <SelectedRows
          loading={itemsLoading}
          selected={pagedSelectedItems}
          removeOption={removeOption}
          totalCount={selectedCount}
        />
        <ResourcePaginator
          pageSize={SELECTED_ITEMS_PAGE_SIZE}
          pageCount={selectedItemsPageCount}
          totalResources={selectedCount}
          currentPage={selectedItemsCurrentPage}
          onPageChange={onSelectedItemsPageChange}
        />
      </div>
    </>
  )
}
