import {useMemo, useState} from 'react'
import {Button, Label} from '@primer/react'

import AIUsageSummaryCard, {getCfiProgressBarColor} from './AIUsageSummaryCard'
import AdditionalUsageBudgetDialog from './AdditionalUsageBudgetDialog'
import InfoIconOverlay from '../InfoIconOverlay'
import styles from './AIUsageSummaryCardContainer.module.css'
import {RequestState} from '../../../enums'

import type {CfiQuota} from '../../../types/usage'
import {useRoutePayload} from '@github-ui/react-core/use-route-payload'
import type {AIUsagePagePayload} from '../../../routes/AIUsagePage'
import {formatMoneyDisplay, parseMoneyString} from '../../../utils'

function formatPlanLabel(plan: string) {
  const planName = plan
    .split('_')
    .map(word => word.charAt(0).toUpperCase() + word.slice(1))
    .join(' ')
  return `Copilot ${planName}`
}

interface CfiSummaryCardsProps {
  budgetsUrl: string
  overage: CfiQuota['overage']
  creditsEntitlement: number
  creditsUsed: number
  resetLabel: string
}

export default function CfiSummaryCards(props: CfiSummaryCardsProps) {
  const {overage, creditsEntitlement, creditsUsed, resetLabel, budgetsUrl} = props
  const [isBudgetDialogOpen, setIsBudgetDialogOpen] = useState(false)
  const [budgetAmount, setBudgetAmount] = useState(() => parseMoneyString(overage.budget_amount))
  const budgetExists = budgetAmount > 0
  const formattedBudget = useMemo(() => formatMoneyDisplay(budgetAmount, 0), [budgetAmount])
  const currentSpend = useMemo(() => parseMoneyString(overage.amount_spent), [overage.amount_spent])
  const overagePercentUsed = useMemo(() => {
    if (budgetAmount <= 0) {
      return currentSpend > 0 ? 100 : 0
    }
    return Math.min(Math.max((currentSpend / budgetAmount) * 100, 0), 100)
  }, [currentSpend, budgetAmount])
  const payload = useRoutePayload<AIUsagePagePayload>()
  const {customer, copilot_plan} = payload

  const hasCreditsEntitlement = creditsEntitlement > 0
  const percentUsed = hasCreditsEntitlement ? Math.floor((creditsUsed / creditsEntitlement) * 100) : 0

  return (
    <div className={styles.cfiSummaryCardsGrid}>
      <AIUsageSummaryCard
        title={
          <>
            <span>Included credits</span>
            <InfoIconOverlay
              infoLabel="About included credits"
              overlayTitle="Included credits"
              overlayText={[
                'AI credits included with your plan, reset monthly. Enable additional usage to continue with pay-as-you-go credits once your run out of your included usage.',
              ]}
            />
            {copilot_plan && (
              <Label className="ml-auto" variant="secondary">
                {formatPlanLabel(copilot_plan)}
              </Label>
            )}
          </>
        }
        value={creditsUsed}
        description={resetLabel}
        testId="credit-usage-card"
        requestState={RequestState.IDLE}
        showProgressBar
        entitlementValue={creditsEntitlement}
        progressValue={creditsUsed}
        progressAriaLabel="Included usage progress"
        progressAriaValueText={`${creditsUsed} of ${creditsEntitlement} credits used`}
        progressBarColor={getCfiProgressBarColor(percentUsed)}
        variant="ai-usage"
      />
      <AIUsageSummaryCard
        title={
          <>
            <span>Additional usage</span>
            <InfoIconOverlay
              infoLabel="About Additional Usage"
              overlayTitle="Additional Usage"
              overlayText={[
                'Pay-as-you-go usage of additional AI credits once you run out of your included usage. Set a budget to cap your maximum monthly spend.',
              ]}
            />
            {budgetsUrl && (
              <Button
                variant="link"
                size="small"
                className="text-normal ml-auto"
                onClick={() => setIsBudgetDialogOpen(true)}
              >
                Edit budget
              </Button>
            )}
          </>
        }
        value={currentSpend === 0 ? '$0' : overage.amount_spent}
        description={budgetExists ? 'Enabled' : 'Not enabled'}
        testId="cfi-additional-usage-card"
        requestState={RequestState.IDLE}
        showProgressBar
        entitlementValue={100}
        progressValue={overagePercentUsed}
        customEntitlementText={`/ ${formattedBudget} budget`}
        progressAriaLabel="Additional usage progress"
        progressAriaValueText={`${overage.amount_spent} of ${formattedBudget} budget spent`}
        progressBarColor={getCfiProgressBarColor(overagePercentUsed)}
      />
      {isBudgetDialogOpen && (
        <AdditionalUsageBudgetDialog
          budgetId={overage.budget_uuid}
          budgetAmount={budgetAmount}
          customerId={customer.customerId}
          budgetsUrl={budgetsUrl}
          onClose={(updatedBudgetAmount?: number) => {
            if (updatedBudgetAmount !== undefined) {
              setBudgetAmount(updatedBudgetAmount)
            }

            setIsBudgetDialogOpen(false)
          }}
        />
      )}
    </div>
  )
}
