import {useState, useRef} from 'react'
import {Button, Link} from '@primer/react'
import {Dialog} from '@primer/react/experimental'
import type {PricingDetails} from '../../types/pricings'
import styles from './PricingDetailsDialog.module.css'

interface Props {
  pricingDetails: PricingDetails
}

export default function PricingDetailsDialog({pricingDetails}: Props) {
  const [isDialogOpen, setIsDialogOpen] = useState(false)
  const returnFocusRef = useRef(null)

  const skuQueryURL = `webevents%0D%0A%7C+where+data.sku%3D%3D"${pricingDetails.sku}"%0D%0A`

  return (
    <div data-testid="pricing-details-list-dialog-container">
      <Button className={styles.skuButton} variant="invisible" onClick={() => setIsDialogOpen(true)}>
        {pricingDetails.sku.replace(/_/g, ' ')}
      </Button>

      {isDialogOpen && (
        <Dialog
          onClose={() => setIsDialogOpen(false)}
          title={pricingDetails.sku.replace(/_/g, ' ')}
          subtitle={<Link href={`/stafftools/audit_log?query=${skuQueryURL}`}>View SKU related events</Link>}
          returnFocusRef={returnFocusRef}
          aria-labelledby="header"
          className={styles.dialog}
        >
          <div className={styles.dialogContent}>
            <ul className="mt-0 pt-0">
              <li className={styles.listItemFirst} data-testid="pricing-sku">
                <span className={styles.labelText}>Pricing SKU:</span>
                <span className={styles.valueText}>{pricingDetails.sku}</span>
              </li>

              <li className={styles.listItem} data-testid="pricing-friendly-name">
                <span className={styles.labelText}>Pricing friendly name:</span>
                <span className={styles.valueText}>{pricingDetails.friendlyName}</span>
              </li>

              <li className={styles.listItem} data-testid="pricing-product">
                <span className={styles.labelText}>Product:</span>
                <span className={styles.valueText}>{pricingDetails.product}</span>
              </li>

              <li className={styles.listItem} data-testid="pricing-public-repo">
                {/* eslint-disable-next-line @github-ui/dotcom-primer/no-title-case -- baselined during linter rollout */}
                <span className={styles.labelText}>Free for Public Repositories:</span>
                <span className={styles.valueText}>{String(pricingDetails.freeForPublicRepos)}</span>
              </li>

              <li className={styles.listItem} data-testid="pricing-price">
                <span className={styles.labelText}>Price:</span>
                <span className={styles.valueText}>${String(pricingDetails.price)}</span>
              </li>

              <li className={styles.listItem} data-testid="pricing-unit-type">
                <span className={styles.labelText}>Unit type:</span>
                <span className={styles.valueText}>{String(pricingDetails.unitType)}</span>
              </li>

              <li className={styles.listItem} data-testid="pricing-meter-type">
                <span className={styles.labelText}>Meter type:</span>
                <span className={styles.valueText}>{String(pricingDetails.meterType)}</span>
              </li>

              <li className={styles.listItem} data-testid="pricing-effective-at">
                <span className={styles.labelText}>Effective at:</span>
                <span className={styles.valueText}>{new Date(pricingDetails.effectiveAt * 1000).toLocaleString()}</span>
              </li>

              <li className={styles.listItem} data-testid="pricing-azure-id">
                <span className={styles.labelText}>Azure meter ID:</span>
                <span className={styles.valueText}>{String(pricingDetails.azureMeterId)}</span>
              </li>

              {pricingDetails.effectiveDatePrices && pricingDetails.effectiveDatePrices.length > 0 && (
                <li className={styles.listItem} data-testid="pricing-historical-prices">
                  <span className={styles.labelText}>Historical prices:</span>
                  <span className={styles.valueTextWide}>
                    {pricingDetails.effectiveDatePrices &&
                      pricingDetails.effectiveDatePrices.map((effectiveDatePrice, index) => (
                        // eslint-disable-next-line @eslint-react/no-array-index-key
                        <div key={index}>
                          <div className={styles.flexRow} data-testid={`pricing-start-date-${index}`}>
                            <span className={styles.labelText}>Start date:</span>
                            <span>{effectiveDatePrice.startDate}</span>
                          </div>
                          <div className={styles.flexRow} data-testid={`pricing-end-date-${index}`}>
                            <span className={styles.labelText}>End date:</span>
                            <span>{effectiveDatePrice.endDate}</span>
                          </div>
                          <div className={styles.flexRow} data-testid={`pricing-date-price-${index}`}>
                            <span className={styles.labelText}>Price:</span>
                            <span>{effectiveDatePrice.price}</span>
                          </div>
                          <br />
                        </div>
                      ))}
                  </span>
                </li>
              )}
            </ul>
          </div>
        </Dialog>
      )}
    </div>
  )
}
