import {use} from 'react'
import {HistoryIcon} from '@primer/octicons-react'
import {Heading, Link} from '@primer/react'

import {PageContext} from '../../../App'
import {GROUP_BY_NONE_TYPE, USAGE_REPORT_LAST_MONTH_PERIOD} from '../../../constants'
import {USAGE_ROUTE} from '../../../routes'
import useRoute from '../../../hooks/use-route'
import GetUsageReportDialog from '../GetUsageReportDialog'
import styles from './AIUsagePreLaunchEmptyState.module.css'
import {UsagePeriod} from '../../../enums'

import type {Filters, ReportTypeSelection} from '../../../types/usage'

interface Props {
  filters: Filters
  currentUserEmail?: string
  disableUsageReports: boolean
  minCustomDate: string
  reportTypeSelections: ReportTypeSelection[]
  isCfiUser?: boolean
  isTokenBasedBillingEnabled?: boolean
}

export default function AIUsagePreLaunchEmptyState({
  filters,
  currentUserEmail,
  disableUsageReports,
  minCustomDate,
  reportTypeSelections,
  isCfiUser = false,
  isTokenBasedBillingEnabled = false,
}: Props) {
  const {isEnterpriseRoute, isOrganizationRoute} = use(PageContext)

  const periodParam = filters.period?.type?.toString() ?? ''
  const customerParam = filters.customer?.id ?? ''

  const {path: meteredUsagePath} = useRoute(
    USAGE_ROUTE,
    {},
    {
      period: periodParam,
      group: String(GROUP_BY_NONE_TYPE),
      customer: customerParam,
      query: 'sku:copilot_premium_request',
    },
  )

  const showMeteredUsageLink = (isEnterpriseRoute || isOrganizationRoute) && !isCfiUser

  return (
    <div className={styles.Container} data-testid="ai-usage-pre-launch-empty-state">
      <HistoryIcon size={24} className={styles.Icon} />
      <Heading as="h2" className={styles.Heading}>
        Accessing historical usage
      </Heading>
      <p className={styles.Description}>
        {showMeteredUsageLink ? (
          <span>
            GitHub now uses{' '}
            <Link href="https://gh.io/copilot-billing-blog" inline target="_blank" rel="noopener noreferrer">
              AI credits
            </Link>{' '}
            to track Copilot usage. Your past usage in premium request units for the selected timeframe is available via
            the AI usage report, premium request analytics API, and the metered usage report.
          </span>
        ) : (
          <span>
            GitHub now uses{' '}
            <Link href="https://gh.io/copilot-billing-blog" inline target="_blank" rel="noopener noreferrer">
              AI credits
            </Link>{' '}
            to track Copilot usage. Your past usage in premium request units for the selected timeframe is available via
            the AI usage report.
          </span>
        )}
      </p>
      <div className={styles.Actions}>
        {currentUserEmail && (
          <GetUsageReportDialog.Trigger
            currentUserEmail={currentUserEmail}
            disableUsageReports={disableUsageReports}
            initialUsageReportPeriod={
              filters.period?.type === UsagePeriod.LAST_MONTH ? USAGE_REPORT_LAST_MONTH_PERIOD : undefined
            }
            minCustomDate={minCustomDate}
            reportTypeSelections={reportTypeSelections}
            premiumRequestVariant
            isTokenBasedBillingEnabled={isTokenBasedBillingEnabled}
          />
        )}
        {showMeteredUsageLink && <Link href={meteredUsagePath}>View metered usage</Link>}
      </div>
    </div>
  )
}
