import {lazy, Suspense, use, useEffect, useState} from 'react'
import {useSearchParams} from '@github-ui/use-navigate'
import {useRoutePayload} from '@github-ui/react-core/use-route-payload'
import {PageBannerOutlet} from '@github-ui/page-banner'
import {updateUrl} from '@github-ui/history'
import {SegmentedControl} from '@primer/react'
import first from 'lodash-es/first'

import {PageContext} from '../App'
import {
  GetUsageReportDialog,
  UsageChartSkeleton,
  UsageFilters,
  AIUsageSummaryCardContainer,
  AIUsageTable,
} from '../components/usage'
import {Layout} from '../components'
import CopilotTrustTierLimitHitBanner, {
  type CopilotTrustTierLimitHitBannerProps,
} from '@github-ui/copilot-trust-tier-limit-hit-banner'
import {reverse} from '../utils/array'
import {DEFAULT_PREMIUM_REQUESTS_GROUP_TYPE} from '../constants'
import {
  USAGE_CHART_SELECTION_CUMULATIVE,
  USAGE_CHART_SELECTION_DAILY,
  USAGE_CHART_SELECTION_MONTHLY,
} from '../constants/chart'
import {createUsageUrlParams} from '../utils/create-usage-url-params'
import {isPeriodBeforeLaunch} from '../utils/is-period-before-launch'
import {getPeriodText} from '../utils'
import {AIUsageUnitType, AIUsageViewMode, RequestState, UsagePeriod} from '../enums'
import useCopilotUsageChartData from '../hooks/usage/use-copilot-usage-chart-data'
import AIUsagePreLaunchEmptyState from '../components/usage/AIUsage/AIUsagePreLaunchEmptyState'
import styles from './AIUsagePage.module.css'

import type {Customer} from '../types/common'
import type {
  CustomerSelection,
  Filters,
  GroupSelection,
  PeriodSelection,
  ReportTypeSelection,
  CfiQuota,
} from '../types/usage'
import AIUsageUserChartSkeleton from '../components/usage/AIUsage/AIUsageUserChartSkeleton'
import AIUsageUserTable from '../components/usage/AIUsage/AIUsageUserTable'

const UsageChart = lazy(() => import('../components/usage/UsageChart'))
const AIUsageUserChart = lazy(() => import('../components/usage/AIUsage/AIUsageUserChart'))

export interface AIUsagePagePayload {
  customer: Customer
  customer_selections: CustomerSelection[]
  group_selections: GroupSelection[]
  period_selections: PeriodSelection[]
  current_user_email?: string
  slug: string
  can_request_all_usage?: boolean
  is_copilot_standalone?: boolean
  report_type_selections: ReportTypeSelection[]
  min_custom_date: string
  disable_usage_reports: boolean
  overage_enabled?: boolean
  cfi_quota?: CfiQuota
  ai_usage_launch_date?: string
  is_token_based_billing_enabled?: boolean
  copilot_plan?: string
  copilot_trust_tier_limit_hit_banner?: CopilotTrustTierLimitHitBannerProps
}

export function AIUsagePage() {
  const payload = useRoutePayload<AIUsagePagePayload>()
  const {
    customer,
    customer_selections,
    group_selections: groupSelections,
    period_selections: periodSelections,
    current_user_email: currentUserEmail,
    can_request_all_usage: canRequestAllUsage = false,
    is_copilot_standalone: isCopilotStandalone = false,
    report_type_selections: reportTypeSelections,
    min_custom_date: minCustomDate,
    disable_usage_reports: disableUsageReports,
    overage_enabled: overageEnabled,
    cfi_quota: cfiQuota,
    ai_usage_launch_date: aiUsageLaunchDate,
    is_token_based_billing_enabled: isTokenBasedBillingEnabled = false,
    copilot_trust_tier_limit_hit_banner: copilotTrustTierLimitHitBanner,
  } = payload

  const {isEnterpriseRoute, isOrganizationRoute} = use(PageContext)
  const showOrgEnterpriseControls = (isEnterpriseRoute || isOrganizationRoute) && !cfiQuota

  const customerSelections = reverse(customer_selections)
  const [searchParams] = useSearchParams()

  const getPeriodType = () => {
    const inputPeriod = searchParams.get('period')
    return inputPeriod ? parseInt(inputPeriod) : UsagePeriod.DEFAULT
  }

  const getDefaultChartSelection = () => {
    const periodType = getPeriodType()
    const isMonthlyPeriod = periodType === UsagePeriod.THIS_MONTH || periodType === UsagePeriod.LAST_MONTH
    return isMonthlyPeriod ? USAGE_CHART_SELECTION_DAILY : USAGE_CHART_SELECTION_MONTHLY
  }

  const getChartSelection = () => {
    const urlParam = searchParams.get('chart_selection')

    if (urlParam) {
      const numericValue = parseInt(urlParam)
      if (!isNaN(numericValue)) {
        const allOptions = [
          USAGE_CHART_SELECTION_CUMULATIVE,
          USAGE_CHART_SELECTION_DAILY,
          USAGE_CHART_SELECTION_MONTHLY,
        ]
        const validOption = allOptions.find(option => option.value === numericValue)
        if (validOption) return validOption
      }
    }

    return getDefaultChartSelection()
  }

  const setUsageFilters = () => {
    const inputGroup = searchParams.get('group')
    const inputQuery = searchParams.get('query')
    const inputCustomer = searchParams.get('customer')
    const inputPage = searchParams.get('page')

    return {
      customer: inputCustomer
        ? ((customerSelections.find((obj: CustomerSelection) => obj.id === inputCustomer) as CustomerSelection) ??
          (first(customerSelections) as CustomerSelection))
        : (first(customerSelections) as CustomerSelection),
      group: groupSelections.find(
        (obj: GroupSelection) => obj.type === (inputGroup ? parseInt(inputGroup) : DEFAULT_PREMIUM_REQUESTS_GROUP_TYPE),
      ),
      period: periodSelections.find((obj: PeriodSelection) => obj.type === getPeriodType()),
      product: undefined,
      sku: undefined,
      searchQuery: inputQuery ?? '',
      chartSelection: getChartSelection(),
      page: inputPage ? parseInt(inputPage) : 1,
    }
  }

  const [filters, setFilters] = useState<Filters>(setUsageFilters)
  const {usageChartData, requestState} = useCopilotUsageChartData({filters, unitType: AIUsageUnitType.AI_UNITS})
  const [viewMode, setViewMode] = useState<AIUsageViewMode>(() => {
    const view = searchParams.get('view')
    return view === AIUsageViewMode.TIME ? AIUsageViewMode.TIME : AIUsageViewMode.MODELS
  })

  useEffect(() => {
    const params = createUsageUrlParams(filters)

    if (params.get('view') !== viewMode) {
      params.set('view', viewMode)
    }

    updateUrl(`?${params.toString()}`)
  }, [filters, viewMode])

  const hasNoUsageData = requestState === RequestState.IDLE && usageChartData.every(series => series.data.length === 0)

  const shouldShowPreLaunchEmptyState = () => {
    if (!aiUsageLaunchDate || !filters.period) return false
    const launchDate = new Date(aiUsageLaunchDate)
    return isPeriodBeforeLaunch(filters.period.type, launchDate) && hasNoUsageData
  }

  const showPreLaunchEmptyState = shouldShowPreLaunchEmptyState()

  const periodType = filters?.period?.type
  const isYearlyPeriod = periodType === UsagePeriod.THIS_YEAR || periodType === UsagePeriod.LAST_YEAR
  const chartSelectionText = isYearlyPeriod ? 'Months' : 'Days'

  return (
    <Layout>
      <PageBannerOutlet />
      <GetUsageReportDialog>
        <>
          <GetUsageReportDialog.Notifications />
          <header className={styles.pageHeader}>
            <div className={`${styles.pageHeaderContent} flex-items-center tmp-mb-1`}>
              <div className={styles.pageHeaderLeft}>
                <h1 className={styles.pageHeading}>AI usage</h1>
              </div>
              <div className={styles.pageHeaderRight}>
                {currentUserEmail && showOrgEnterpriseControls && (
                  <GetUsageReportDialog.Trigger
                    currentUserEmail={currentUserEmail}
                    disableUsageReports={disableUsageReports}
                    minCustomDate={minCustomDate}
                    reportTypeSelections={reportTypeSelections}
                    premiumRequestVariant
                    isTokenBasedBillingEnabled={isTokenBasedBillingEnabled}
                  />
                )}

                {!showOrgEnterpriseControls && (
                  <div className={`${styles.userControlsRow} tmp-mb-0`}>
                    <div className={styles.userControlsRight}>
                      <SegmentedControl aria-label="Chart view">
                        <SegmentedControl.Button
                          selected={viewMode === AIUsageViewMode.MODELS}
                          onClick={() => setViewMode(AIUsageViewMode.MODELS)}
                        >
                          Models
                        </SegmentedControl.Button>
                        <SegmentedControl.Button
                          selected={viewMode === AIUsageViewMode.TIME}
                          onClick={() => setViewMode(AIUsageViewMode.TIME)}
                        >
                          {chartSelectionText}
                        </SegmentedControl.Button>
                      </SegmentedControl>
                      <UsageFilters
                        customer={customer}
                        filters={filters}
                        setFilters={setFilters}
                        groupSelections={[]}
                        periodSelections={periodSelections}
                        showSearch={false}
                        isCopilotStandalone={false}
                        isEnterpriseOrgAdmin={false}
                        periodTextOverride={getPeriodText(filters.period, {shorten: true})}
                        compact
                        periodFilterClassName={styles.periodFilterNoMarginLeft}
                        hideGroupFilter
                        premiumRequestsVariant
                      />
                      {currentUserEmail && (
                        <GetUsageReportDialog.Trigger
                          currentUserEmail={currentUserEmail}
                          disableUsageReports={disableUsageReports}
                          minCustomDate={minCustomDate}
                          reportTypeSelections={reportTypeSelections}
                          premiumRequestVariant
                          isTokenBasedBillingEnabled={isTokenBasedBillingEnabled}
                          compact
                          hasCfiQuota
                        />
                      )}
                    </div>
                  </div>
                )}
              </div>
            </div>
          </header>
        </>
        <div>
          {copilotTrustTierLimitHitBanner && (
            <div className="tmp-mb-3">
              <CopilotTrustTierLimitHitBanner {...copilotTrustTierLimitHitBanner} />
            </div>
          )}
          {showOrgEnterpriseControls && (
            <UsageFilters
              customer={customer}
              filters={filters}
              setFilters={setFilters}
              groupSelections={groupSelections}
              periodSelections={periodSelections}
              showSearch={showOrgEnterpriseControls}
              searchPlaceholder="Filter by user, model, organization or cost center"
              premiumRequestsVariant
              isCopilotStandalone={isCopilotStandalone}
              isEnterpriseOrgAdmin={!canRequestAllUsage}
            />
          )}

          {cfiQuota && (
            <AIUsageSummaryCardContainer filters={filters} overageEnabled={overageEnabled} cfiQuota={cfiQuota} />
          )}

          {showPreLaunchEmptyState ? (
            <AIUsagePreLaunchEmptyState
              filters={filters}
              currentUserEmail={currentUserEmail}
              disableUsageReports={disableUsageReports}
              minCustomDate={minCustomDate}
              reportTypeSelections={reportTypeSelections}
              isCfiUser={!!cfiQuota}
              isTokenBasedBillingEnabled={isTokenBasedBillingEnabled}
            />
          ) : (
            <>
              {!cfiQuota && (
                <AIUsageSummaryCardContainer filters={filters} overageEnabled={overageEnabled} cfiQuota={cfiQuota} />
              )}

              <Suspense
                fallback={
                  showOrgEnterpriseControls ? (
                    <UsageChartSkeleton copilotVariant noneGroupingTitle="AI credits usage" filters={filters} />
                  ) : (
                    <AIUsageUserChartSkeleton filters={filters} />
                  )
                }
              >
                {showOrgEnterpriseControls ? (
                  <UsageChart
                    requestState={requestState}
                    usage={usageChartData}
                    filters={filters}
                    copilotVariant
                    noneGroupingTitle="AI credits usage"
                    billedLabel="Additional usage"
                    onFiltersChange={setFilters}
                  />
                ) : (
                  <AIUsageUserChart
                    requestState={requestState}
                    usage={usageChartData}
                    filters={filters}
                    viewMode={viewMode}
                  />
                )}
              </Suspense>
              {showOrgEnterpriseControls ? (
                <AIUsageTable filters={filters} setFilters={setFilters} variant="ai-usage" />
              ) : (
                <AIUsageUserTable filters={filters} viewMode={viewMode} />
              )}
            </>
          )}
        </div>
      </GetUsageReportDialog>
    </Layout>
  )
}
