import {useState, useMemo} from 'react'
// eslint-disable-next-line no-restricted-imports
import {useToastContext} from '@github-ui/toast/ToastContext'
import {useFeatureFlag} from '@github-ui/react-core/use-feature-flag'

import useRequest from '../use-request'

import {COST_CENTERS_ROUTE} from '../../routes'

import type {CostCenter} from '../../types/cost-centers'
import {RequestState} from '../../enums'

const ERRORS = {
  QUERY_COST_CENTERS_ERROR: 'Unable to query cost centers',
}

const COST_CENTERS_PAGE_SIZE = 10

interface UseCostCentersPageProps {
  page?: number
  pageSize?: number
  state?: 'active' | 'deleted'
  noop?: boolean
  refetchKey?: number
  query?: string
  /** Force pagination params to be sent regardless of feature flag (for pickers) */
  forcePagination?: boolean
  /** Keep previous data visible during loading instead of clearing it (useful for pickers) */
  preserveStaleData?: boolean
}

interface GetCostCentersPaginatedResponse {
  activeCostCenters: CostCenter[]
  archivedCostCenters: CostCenter[]
  hasNextPage: boolean
  hasUserScopedCostCenters: boolean
  totalCount?: number
}

interface UseCostCentersPageReturn {
  activeCostCenters: CostCenter[]
  archivedCostCenters: CostCenter[]
  hasNextPage: boolean
  hasUserScopedCostCenters: boolean
  requestState: RequestState
  isPaginationEnabled: boolean
  totalCount: number
}

/**
 * Custom hook for fetching cost centers with pagination support.
 * Similar to useBudgetsPage, this hook handles client-side data fetching
 * and tracks loading state for showing skeleton loading tables.
 *
 * @param props - Optional pagination and filter parameters
 * @returns Cost centers data, pagination metadata, and loading state
 */
function useCostCentersPageWithLoading({
  page = 1,
  pageSize = COST_CENTERS_PAGE_SIZE,
  state = 'active',
  noop = false,
  refetchKey = 0,
  query = '',
  forcePagination = false,
  preserveStaleData = false,
}: UseCostCentersPageProps = {}): UseCostCentersPageReturn {
  const [activeCostCenters, setActiveCostCenters] = useState<CostCenter[]>([])
  const [archivedCostCenters, setArchivedCostCenters] = useState<CostCenter[]>([])
  const [hasNextPage, setHasNextPage] = useState(false)
  const [hasUserScopedCostCenters, setHasUserScopedCostCenters] = useState(false)
  const [totalCount, setTotalCount] = useState(0)
  const {addToast} = useToastContext()

  // Use the feature flag hooks to ensure reactivity when flags are toggled
  /* eslint-disable-next-line @github-ui/github-monorepo/no-use-feature-flags --
     TODO: Migrate to isFeatureEnabled from @github-ui/feature-flags. See
     https://thehub.github.com/epd/engineering/dev-practicals/frontend/react/data-router/migration/app-payload-deprecation/ */
  const billingCostCentersUIPagination = useFeatureFlag('billing_cost_centers_ui_pagination_enabled')
  /* eslint-disable-next-line @github-ui/github-monorepo/no-use-feature-flags --
     TODO: Migrate to isFeatureEnabled from @github-ui/feature-flags. See
     https://thehub.github.com/epd/engineering/dev-practicals/frontend/react/data-router/migration/app-payload-deprecation/ */
  const disableOrgAdminPagination = useFeatureFlag('billing_cost_centers_disable_org_admin_pagination')
  const isPaginationEnabled = billingCostCentersUIPagination && !disableOrgAdminPagination

  // Initialize to LOADING when pagination is enabled so loading table shows immediately on server-side navigation
  const [requestState, setRequestState] = useState<RequestState>(
    noop ? RequestState.IDLE : isPaginationEnabled ? RequestState.LOADING : RequestState.INIT,
  )

  const reqParams = useMemo(() => {
    const shouldPaginate = isPaginationEnabled || forcePagination
    if (!shouldPaginate) {
      return undefined
    }

    const params: Record<string, string> = {
      page: String(page),
      page_size: String(pageSize),
      state,
    }

    if (query) {
      params.searchName = query
    }

    return params
  }, [isPaginationEnabled, forcePagination, page, pageSize, state, query])

  useRequest({
    route: COST_CENTERS_ROUTE,
    reqParams,
    noop,
    requestKey: refetchKey,
    onStart: () => {
      if (!preserveStaleData) {
        setActiveCostCenters([])
        setArchivedCostCenters([])
      }
      setRequestState(RequestState.LOADING)
    },
    onSuccess: response => {
      const payload = response.data.payload as GetCostCentersPaginatedResponse

      // Validate response has required fields
      if (!Array.isArray(payload.activeCostCenters) || !Array.isArray(payload.archivedCostCenters)) {
        // eslint-disable-next-line @github-ui/dotcom-primer/toast-migration
        addToast({
          type: 'error',
          message: ERRORS.QUERY_COST_CENTERS_ERROR,
        })
        setRequestState(RequestState.ERROR)
        return
      }

      setActiveCostCenters(payload.activeCostCenters || [])
      setArchivedCostCenters(payload.archivedCostCenters || [])
      setHasNextPage(payload.hasNextPage ?? false)
      setHasUserScopedCostCenters(payload.hasUserScopedCostCenters ?? false)
      setTotalCount(payload.totalCount ?? 0)
      setRequestState(RequestState.IDLE)
    },
    onError: () => {
      // eslint-disable-next-line @github-ui/dotcom-primer/toast-migration
      addToast({
        type: 'error',
        message: ERRORS.QUERY_COST_CENTERS_ERROR,
      })
      setRequestState(RequestState.ERROR)
    },
  })

  return {
    activeCostCenters,
    archivedCostCenters,
    hasNextPage,
    hasUserScopedCostCenters,
    requestState,
    isPaginationEnabled,
    totalCount,
  }
}

export default useCostCentersPageWithLoading
