import {Link} from '@primer/react'
import {COPILOT_MANAGE_POLICIES_BASE_ROUTE_ORGS, COPILOT_MANAGE_POLICIES_BASE_ROUTE_ENT} from '../../routes'
import useRoute from '../../hooks/use-route'

interface Props {
  isOrganizationRoute: boolean
  isTokenBasedBillingEnabled?: boolean
}

export function BudgetCopilotPolicyLink({isOrganizationRoute, isTokenBasedBillingEnabled = false}: Props) {
  const {path: policyRoute} = useRoute(
    isOrganizationRoute ? COPILOT_MANAGE_POLICIES_BASE_ROUTE_ORGS : COPILOT_MANAGE_POLICIES_BASE_ROUTE_ENT,
  )

  return (
    <Link inline href={policyRoute} target="_blank" rel="noreferrer">
      {isTokenBasedBillingEnabled ? 'overages spend is enabled.' : 'paid usage is enabled.'}
    </Link>
  )
}
